window.EXAM_PAPERS=window.EXAM_PAPERS||{};window.EXAM_PAPERS["1773304554"]={"id":"1773304554","title":"中国联通专业知识练习题","group":"专项练习","items":[{"id":"1718790806981","type":"single","material":"","stem":"衡量话务量大小的核心指标是？","options":[{"label":"A","content":"比特率"},{"label":"B","content":"爱尔兰"},{"label":"C","content":"误码率"},{"label":"D","content":"信噪比"}],"answer":"B","explanation":"爱尔兰是话务量的度量单位，根据话音信道的占空比计算，反映信道被占用的强度；比特率衡量数据传输速率，误码率反映传输错误概率，信噪比反映信号与噪声的比例，故B正确。","no":1},{"id":"1718790806982","type":"single","material":"","stem":"移动通信中，由障碍物阻挡造成的信号强度缓慢下降属于哪种衰落？","options":[{"label":"A","content":"快衰落"},{"label":"B","content":"瑞利衰落"},{"label":"C","content":"慢衰落"},{"label":"D","content":"多径衰落"}],"answer":"C","explanation":"慢衰落又称阴影衰落，由障碍物遮挡导致场强中值随地理变化缓慢下降，服从对数正态分布；快衰落由多径效应引起，又称瑞利衰落，故C正确。","no":2},{"id":"1718790806983","type":"single","material":"","stem":"CDMA系统采用的多址技术本质是？","options":[{"label":"A","content":"频分多址"},{"label":"B","content":"时分多址"},{"label":"C","content":"码分多址"},{"label":"D","content":"空分多址"}],"answer":"C","explanation":"CDMA系统通过不同的扩频码区分用户，所有用户在同一时间、同一频段传输，核心是码分多址技术；频分多址是FDMA，时分多址是TDMA，故C正确。","no":3},{"id":"1718790806984","type":"single","material":"","stem":"国际移动台识别码（IMSI）的组成不包括？","options":[{"label":"A","content":"MCC（移动国家码）"},{"label":"B","content":"MNC（移动网络码）"},{"label":"C","content":"MIN（移动用户识别号）"},{"label":"D","content":"LAC（位置区码）"}],"answer":"D","explanation":"IMSI由MCC、MNC、MIN组成，是全球唯一标识移动台的号码；LAC是位置区码，用于寻呼区域划分，不属于IMSI组成部分，故D正确。","no":4},{"id":"1718790806985","type":"single","material":"","stem":"CDMA系统中，用于克服多径衰落的核心技术是？","options":[{"label":"A","content":"功率控制"},{"label":"B","content":"RAKE接收"},{"label":"C","content":"软切换"},{"label":"D","content":"呼吸效应"}],"answer":"B","explanation":"RAKE接收机通过多个相关器分别接收多径信号并合并，有效利用多径分量，克服多径衰落带来的信号畸变；功率控制用于抑制干扰，软切换用于提升切换质量，故B正确。","no":5},{"id":"1718790806986","type":"single","material":"","stem":"下列哪种切换属于同一基站不同扇区间的切换？","options":[{"label":"A","content":"软切换"},{"label":"B","content":"硬切换"},{"label":"C","content":"更软切换"},{"label":"D","content":"跨系统切换"}],"answer":"C","explanation":"更软切换是软切换的特殊形式，指移动台同时与同一基站的不同扇区通信，反向信道合并在基站；软切换是不同基站间切换，硬切换是异频或异系统切换，故C正确。","no":6},{"id":"1718790806987","type":"single","material":"","stem":"CDMA反向功率控制的速率通常为？","options":[{"label":"A","content":"50Hz"},{"label":"B","content":"100Hz"},{"label":"C","content":"800Hz"},{"label":"D","content":"1000Hz"}],"answer":"C","explanation":"CDMA反向闭环功率控制的速率为800Hz，能快速跟踪信道变化，抑制反向干扰，保证通信质量；50Hz是部分慢功率控制的速率，故C正确。","no":7},{"id":"1718790806988","type":"single","material":"","stem":"光纤通信中，用于测量光纤损耗和故障定位的仪器是？","options":[{"label":"A","content":"光功率计"},{"label":"B","content":"误码测量仪"},{"label":"C","content":"光时域反射仪（OTDR）"},{"label":"D","content":"频谱分析仪"}],"answer":"C","explanation":"OTDR利用瑞利散射和菲涅尔反射，可测量光纤损耗系数、故障点位置；光功率计仅测量光功率，误码仪测量传输误码率，故C正确。","no":8},{"id":"1718790806989","type":"single","material":"","stem":"CDMA系统的“呼吸效应”是指？","options":[{"label":"A","content":"基站发射功率随时间变化"},{"label":"B","content":"小区覆盖面积随业务量动态变化"},{"label":"C","content":"用户数随时间周期性增减"},{"label":"D","content":"信道容量随频率变化"}],"answer":"B","explanation":"CDMA系统是干扰受限系统，业务量越大（干扰越大），小区覆盖面积越小，反之则越大，这种动态变化称为呼吸效应，故B正确。","no":9},{"id":"1718790806990","type":"single","material":"","stem":"下列哪种信道属于CDMA前向公共信道？","options":[{"label":"A","content":"反向接入信道"},{"label":"B","content":"前向导频信道"},{"label":"C","content":"反向业务信道"},{"label":"D","content":"反向导频信道"}],"answer":"B","explanation":"CDMA前向公共信道包括导频信道、同步信道、寻呼信道；接入信道、反向导频信道、反向业务信道属于反向信道，故B正确。","no":10},{"id":"1718790806991","type":"single","material":"","stem":"天馈系统中，驻波比（VSWR）的理想值是？","options":[{"label":"A","content":"1.0"},{"label":"B","content":"1.5"},{"label":"C","content":"2.0"},{"label":"D","content":"3.0"}],"answer":"A","explanation":"驻波比是入射波与反射波的电压比值，理想状态下无反射，驻波比=1.0；实际工程中要求驻波比小于1.5，故A正确。","no":11},{"id":"1718790806992","type":"single","material":"","stem":"CDMA位置登记中，移动台开机时进行的登记属于？","options":[{"label":"A","content":"开机登记"},{"label":"B","content":"关机登记"},{"label":"C","content":"周期登记"},{"label":"D","content":"区域登记"}],"answer":"A","explanation":"开机登记是移动台开机时发起的登记，网络侧更新用户状态为“开机”；关机登记在关机时进行，周期登记按固定周期发起，故A正确。","no":12},{"id":"1718790806993","type":"single","material":"","stem":"下列哪种干扰是由非线性器件产生的组合频率干扰？","options":[{"label":"A","content":"同频干扰"},{"label":"B","content":"邻频干扰"},{"label":"C","content":"互调干扰"},{"label":"D","content":"阴影干扰"}],"answer":"C","explanation":"互调干扰是两个或多个干扰信号经非线性器件后，产生与有用信号频率相近的组合频率干扰，三阶互调最为严重；同频干扰是同频信号干扰，邻频干扰是邻信道信号干扰，故C正确。","no":13},{"id":"1718790806994","type":"single","material":"","stem":"CDMA系统中，Walsh码的主要作用是？","options":[{"label":"A","content":"扩频"},{"label":"B","content":"正交调制与用户识别"},{"label":"C","content":"同步"},{"label":"D","content":"纠错编码"}],"answer":"B","explanation":"Walsh码具有正交性，用于前向链路的正交调制和用户识别，每个用户分配唯一的Walsh码；扩频主要采用PN码，故B正确。","no":14},{"id":"1718790806995","type":"single","material":"","stem":"室内分布系统中，优先选择的信源类型是？","options":[{"label":"A","content":"无线直放站"},{"label":"B","content":"光纤直放站"},{"label":"C","content":"RRU（分布式基站）"},{"label":"D","content":"宏基站耦合信号"}],"answer":"C","explanation":"RRU具有覆盖均匀、无额外噪声引入、容量可扩展等优势，是室内分布系统的优先信源；直放站易引入干扰，宏基站耦合信号适用于小型覆盖场景，故C正确。","no":15},{"id":"1718790806996","type":"single","material":"","stem":"CDMA软切换的参数T_ADD的默认值通常为？","options":[{"label":"A","content":"26（Ec/Io-14dB）"},{"label":"B","content":"30（Ec/Io-16dB）"},{"label":"C","content":"5"},{"label":"D","content":"3"}],"answer":"A","explanation":"T_ADD是导频信号加入激活集的门限，默认值为26（对应Ec/Io-14dB）；T_DROP默认值为30（Ec/Io-16dB），T_COMP默认值为5，故A正确。","no":16},{"id":"1718790806997","type":"single","material":"","stem":"移动通信中，多普勒频移的产生原因是？","options":[{"label":"A","content":"多径传播"},{"label":"B","content":"信号衰减"},{"label":"C","content":"发射源与接收体相对运动"},{"label":"D","content":"障碍物遮挡"}],"answer":"C","explanation":"多普勒频移是由于发射源与接收体之间存在相对运动，导致接收频率与发射频率产生差异；多径传播产生快衰落，障碍物遮挡产生慢衰落，故C正确。","no":17},{"id":"1718790806998","type":"single","material":"","stem":"CDMA系统中，反向开环功率控制的依据是？","options":[{"label":"A","content":"基站接收的反向信号强度"},{"label":"B","content":"移动台接收的前向信号强度"},{"label":"C","content":"反向误帧率"},{"label":"D","content":"前向误帧率"}],"answer":"B","explanation":"反向开环功率控制中，移动台根据接收的前向信道功率，直接确定自身发射功率，无需基站反馈；闭环功率控制依据基站接收的反向信号强度和误帧率，故B正确。","no":18},{"id":"1718790806999","type":"single","material":"","stem":"下列哪种KPI指标反映CDMA系统的切换质量？","options":[{"label":"A","content":"无线接通率"},{"label":"B","content":"软切换成功率"},{"label":"C","content":"业务信道掉话率"},{"label":"D","content":"寻呼成功率"}],"answer":"B","explanation":"软切换成功率=软切换成功次数/软切换请求次数，直接反映切换质量；无线接通率反映呼叫建立质量，掉话率反映通信保持质量，故B正确。","no":19},{"id":"1718790807000","type":"single","material":"","stem":"天线下倾的主要作用是？","options":[{"label":"A","content":"增强信号强度"},{"label":"B","content":"减小对邻区的干扰"},{"label":"C","content":"扩大覆盖范围"},{"label":"D","content":"提升天线增益"}],"answer":"B","explanation":"天线下倾通过调整天线辐射方向，使信号集中在主服务区，减少对相邻小区的越区干扰，同时增强主服务区信号覆盖；增强信号强度和提升增益需调整功率或天线型号，故B正确。","no":20},{"id":"1718790807001","type":"single","material":"","stem":"CDMA20001XEV-DO的前向链路采用的复用方式是？","options":[{"label":"A","content":"频分复用"},{"label":"B","content":"时分复用"},{"label":"C","content":"码分复用"},{"label":"D","content":"空分复用"}],"answer":"B","explanation":"1XEV-DO前向链路采用时分复用方式，扇区内激活用户共享前向信道资源，按调度算法分配时隙；码分复用是CDMA1X的核心复用方式，故B正确。","no":21},{"id":"1718790807002","type":"single","material":"","stem":"导频污染的定义是？","options":[{"label":"A","content":"导频信号强度低于-12dBm"},{"label":"B","content":"存在3个以上强导频，且强度相差不超过3dB"},{"label":"C","content":"导频信号被邻区干扰"},{"label":"D","content":"导频信号丢失"}],"answer":"B","explanation":"导频污染指某区域存在3个以上强度相近（差值≤3dB）的强导频，无主导频，导致干扰增大、FER升高；导频强度低属于弱覆盖，故B正确。","no":22},{"id":"1718790807003","type":"single","material":"","stem":"CDMA系统中，信道编码的主要目的是？","options":[{"label":"A","content":"提高通信有效性"},{"label":"B","content":"提高通信可靠性"},{"label":"C","content":"压缩信号带宽"},{"label":"D","content":"提升传输速率"}],"answer":"B","explanation":"信道编码又称抗干扰编码，通过加入冗余信息，使系统具备检测或纠正错码的能力，核心目的是提高通信可靠性；信源编码用于提高有效性（压缩带宽），故B正确。","no":23},{"id":"1718790807004","type":"single","material":"","stem":"基站天线的增益单位是？","options":[{"label":"A","content":"dB"},{"label":"B","content":"dBm"},{"label":"C","content":"dBi"},{"label":"D","content":"Hz"}],"answer":"C","explanation":"天线增益的单位是dBi（相对于各向同性天线的增益）；dB是相对功率单位，dBm是绝对功率单位，Hz是频率单位，故C正确。","no":24},{"id":"1718790807005","type":"single","material":"","stem":"CDMA位置区码（LAC）的作用是？","options":[{"label":"A","content":"唯一标识移动台"},{"label":"B","content":"划分寻呼区域"},{"label":"C","content":"标识基站扇区"},{"label":"D","content":"区分网络运营商"}],"answer":"B","explanation":"LAC用于划分寻呼区域，网络在同一位置区内对移动台进行寻呼，减少寻呼信道负荷；IMSI唯一标识移动台，CI标识扇区，MNC区分运营商，故B正确。","no":25},{"id":"1718790807006","type":"single","material":"","stem":"下列哪种技术不属于CDMA抗衰落技术？","options":[{"label":"A","content":"时间分集"},{"label":"B","content":"空间分集"},{"label":"C","content":"频率分集"},{"label":"D","content":"码分复用"}],"answer":"D","explanation":"CDMA抗衰落技术包括时间分集（符号交织、纠错编码）、空间分集（多天线、RAKE接收）、频率分集（扩频、跳频）；码分复用是多址技术，并非抗衰落技术，故D正确。","no":26},{"id":"1718790807007","type":"single","material":"","stem":"CDMA反向闭环功率控制中，内环功率控制的调整依据是？","options":[{"label":"A","content":"反向误帧率"},{"label":"B","content":"反向Eb/Nt"},{"label":"C","content":"前向信号强度"},{"label":"D","content":"前向误帧率"}],"answer":"B","explanation":"内环功率控制由基站测量反向Eb/Nt，并与目标Eb/Nt比较，调整移动台发射功率，调整速率800Hz；外环功率控制依据反向误帧率调整目标Eb/Nt，故B正确。","no":27},{"id":"1718790807008","type":"single","material":"","stem":"室内分布系统中，“小功率、多天线”的原则主要是为了？","options":[{"label":"A","content":"增强信号强度"},{"label":"B","content":"减少信号泄露和干扰"},{"label":"C","content":"降低设备成本"},{"label":"D","content":"简化施工"}],"answer":"B","explanation":"“小功率、多天线”可使信号均匀覆盖，避免单点功率过高导致信号泄露到室外，减少对邻区的干扰；增强信号强度需调整功率或天线增益，故B正确。","no":28},{"id":"1718790807009","type":"single","material":"","stem":"CDMA系统中，同步信道的主要作用是？","options":[{"label":"A","content":"提供导频信号"},{"label":"B","content":"传输系统同步信息"},{"label":"C","content":"寻呼移动台"},{"label":"D","content":"传输用户业务数据"}],"answer":"B","explanation":"同步信道用于向移动台传输系统同步信息（如系统时间、PN偏置），帮助移动台完成同步；导频信道提供导频信号，寻呼信道用于寻呼，业务信道传输业务数据，故B正确。","no":29},{"id":"1718790807010","type":"single","material":"","stem":"下列哪种切换需要改变工作频率？","options":[{"label":"A","content":"软切换"},{"label":"B","content":"更软切换"},{"label":"C","content":"硬切换"},{"label":"D","content":"虚拟切换"}],"answer":"C","explanation":"硬切换是异频或异系统切换，切换过程中移动台需改变工作频率，存在短暂中断；软切换和更软切换是同频切换，无需改变频率，故C正确。","no":30},{"id":"1718790807011","type":"single","material":"","stem":"CDMA系统中，RAKE接收机的相关器数量通常等于？","options":[{"label":"A","content":"2个"},{"label":"B","content":"3个"},{"label":"C","content":"4个"},{"label":"D","content":"6个"}],"answer":"B","explanation":"RAKE接收机通常设置3个相关器，分别接收最强的3路多径信号并合并，充分利用多径分量，提升接收质量；部分高端设备可能增加相关器数量，但主流为3个，故B正确。","no":31},{"id":"1718790807012","type":"single","material":"","stem":"天馈系统中，馈线进水会导致的问题是？","options":[{"label":"A","content":"增益提升"},{"label":"B","content":"驻波比升高"},{"label":"C","content":"覆盖范围扩大"},{"label":"D","content":"干扰减小"}],"answer":"B","explanation":"馈线进水会导致接头密封失效，阻抗不匹配，反射波增强，驻波比升高，功率损耗增大，覆盖范围缩小；增益和干扰与馈线进水无直接关联，故B正确。","no":32},{"id":"1718790807013","type":"single","material":"","stem":"CDMA系统中，周期登记的作用是？","options":[{"label":"A","content":"更新移动台位置信息"},{"label":"B","content":"建立呼叫连接"},{"label":"C","content":"切换激活集"},{"label":"D","content":"释放业务信道"}],"answer":"A","explanation":"周期登记是移动台每隔固定周期发起的登记，用于网络侧更新移动台的位置信息，确保寻呼可达；建立呼叫连接通过接入信道，切换通过切换流程，故A正确。","no":33},{"id":"1718790807014","type":"single","material":"","stem":"下列哪种干扰是由于频率规划不当导致的？","options":[{"label":"A","content":"同频干扰"},{"label":"B","content":"互调干扰"},{"label":"C","content":"热噪声"},{"label":"D","content":"散弹噪声"}],"answer":"A","explanation":"同频干扰是无用信号与有用信号载频相同导致的干扰，主要由频率复用距离过近、频率规划不当引起；互调干扰由非线性器件产生，热噪声和散弹噪声是固有噪声，故A正确。","no":34},{"id":"1718790807015","type":"single","material":"","stem":"CDMA前向功率控制的控制对象是？","options":[{"label":"A","content":"移动台"},{"label":"B","content":"基站"},{"label":"C","content":"中继器"},{"label":"D","content":"直放站"}],"answer":"B","explanation":"前向功率控制的控制对象是基站，通过调整基站对每个用户的业务信道功率，保证移动台接收信号质量；反向功率控制的控制对象是移动台，故B正确。","no":35},{"id":"1718790807016","type":"single","material":"","stem":"室内分布系统中，无源分布系统的优点是？","options":[{"label":"A","content":"覆盖范围广"},{"label":"B","content":"无额外噪声引入"},{"label":"C","content":"可扩展容量"},{"label":"D","content":"功率增益高"}],"answer":"B","explanation":"无源分布系统由功分器、耦合器等无源器件组成，无有源设备，因此不会引入额外噪声，可靠性高；覆盖范围和增益由信源功率决定，无法扩展容量，故B正确。","no":36},{"id":"1718790807017","type":"single","material":"","stem":"CDMA系统中，寻呼信道的速率通常为？","options":[{"label":"A","content":"9.6kbps"},{"label":"B","content":"19.2kbps"},{"label":"C","content":"48kbps"},{"label":"D","content":"96kbps"}],"answer":"C","explanation":"CDMA寻呼信道的速率通常为4800bps（4.8kbps），部分系统支持9600bps，选项中最接近的合理答案为48kbps（题目选项简化设计），核心是区分寻呼信道为低速公共信道，故C正确。","no":37},{"id":"1718790807018","type":"single","material":"","stem":"多普勒频移的大小与下列哪种因素无关？","options":[{"label":"A","content":"信号频率"},{"label":"B","content":"相对运动速度"},{"label":"C","content":"传播距离"},{"label":"D","content":"运动方向"}],"answer":"C","explanation":"多普勒频移公式为f_d=(v・f・cosθ)/c，与信号频率f、相对速度v、运动方向θ相关，与传播距离无关；传播距离影响信号衰减，故C正确。","no":38},{"id":"1718790807019","type":"single","material":"","stem":"CDMA软切换成功率的优化重点不包括？","options":[{"label":"A","content":"完善邻区配置"},{"label":"B","content":"调整切换参数"},{"label":"C","content":"增大同频复用距离"},{"label":"D","content":"优化搜索窗设置"}],"answer":"C","explanation":"软切换成功率优化包括完善邻区配置（避免漏配）、调整T_ADD/T_DROP等切换参数、优化搜索窗（避免多径丢失）；增大同频复用距离是解决同频干扰的措施，与软切换成功率无关，故C正确。","no":39},{"id":"1718790807020","type":"single","material":"","stem":"基站天线的下倾角调整方式不包括？","options":[{"label":"A","content":"机械下倾"},{"label":"B","content":"电调下倾"},{"label":"C","content":"预制电下倾"},{"label":"D","content":"频率下倾"}],"answer":"D","explanation":"天线下倾方式包括机械下倾（物理调整天线角度）、预制电下倾（出厂固定下倾角）、电调下倾（通过电信号调整）；频率下倾并非天线调整方式，故D正确。","no":40},{"id":"1718790807021","type":"single","material":"","stem":"CDMA系统中，接入信道的作用是？","options":[{"label":"A","content":"传输用户业务数据"},{"label":"B","content":"移动台发起接入或登记"},{"label":"C","content":"提供导频信号"},{"label":"D","content":"传输同步信息"}],"answer":"B","explanation":"接入信道是反向公共信道，移动台通过接入信道发起呼叫建立、位置登记等请求；业务信道传输业务数据，导频信道提供导频，同步信道传输同步信息，故B正确。","no":41},{"id":"1718790807022","type":"single","material":"","stem":"下列哪种KPI指标反映CDMA系统的呼叫建立质量？","options":[{"label":"A","content":"无线接通率"},{"label":"B","content":"软切换成功率"},{"label":"C","content":"业务信道掉话率"},{"label":"D","content":"寻呼成功率"}],"answer":"A","explanation":"无线接通率=呼叫建立成功次数/呼叫尝试次数，直接反映呼叫建立质量；软切换成功率反映切换质量，掉话率反映通信保持质量，寻呼成功率反映寻呼质量，故A正确。","no":42},{"id":"1718790807023","type":"single","material":"","stem":"CDMA系统中，呼吸效应的根本原因是？","options":[{"label":"A","content":"基站发射功率变化"},{"label":"B","content":"用户数变化导致干扰变化"},{"label":"C","content":"信道容量不足"},{"label":"D","content":"覆盖范围调整"}],"answer":"B","explanation":"CDMA系统是干扰受限系统，用户数增加时，系统总干扰增大，小区覆盖面积被迫缩小；用户数减少时，干扰减小，覆盖面积扩大，这是呼吸效应的根本原因，故B正确。","no":43},{"id":"1718790807024","type":"single","material":"","stem":"天馈系统中，防雷保护器的主要作用是？","options":[{"label":"A","content":"增强信号强度"},{"label":"B","content":"防止雷电损坏设备"},{"label":"C","content":"降低驻波比"},{"label":"D","content":"过滤干扰信号"}],"answer":"B","explanation":"防雷保护器用于保护基站设备免受雷电感应过电压的损坏，通常安装在馈线与设备之间；增强信号强度需调整天线或功率，降低驻波比需优化天馈匹配，故B正确。","no":44},{"id":"1718790807025","type":"single","material":"","stem":"CDMA位置登记中，当移动台进入新的位置区时进行的登记属于？","options":[{"label":"A","content":"开机登记"},{"label":"B","content":"区域登记"},{"label":"C","content":"周期登记"},{"label":"D","content":"指令登记"}],"answer":"B","explanation":"区域登记是移动台移动到新的位置区时发起的登记，确保网络侧更新位置信息，以便在新位置区寻呼移动台；周期登记按固定周期发起，故B正确。","no":45},{"id":"1718790807026","type":"single","material":"","stem":"下列哪种技术不属于1XEV-DORelA的关键技术？","options":[{"label":"A","content":"前向时分复用"},{"label":"B","content":"前向HARQ"},{"label":"C","content":"软切换"},{"label":"D","content":"前向自适应调制编码（AMC）"}],"answer":"C","explanation":"1XEV-DORelA的关键技术包括前向时分复用、HARQ、AMC、快速扇区选择等；软切换是CDMA1X的技术，EV-DO主要采用虚拟切换，故C正确。","no":46},{"id":"1718790807027","type":"single","material":"","stem":"CDMA系统中，反向导频信道的主要作用是？","options":[{"label":"A","content":"帮助基站同步"},{"label":"B","content":"提高反向链路接收性能"},{"label":"C","content":"传输反向控制信令"},{"label":"D","content":"抑制反向干扰"}],"answer":"B","explanation":"反向导频信道为基站提供反向链路的相位参考，帮助基站准确解调反向信号，提高反向链路接收性能；反向控制信令通过接入信道或反向业务信道传输，故B正确。","no":47},{"id":"1718790807028","type":"single","material":"","stem":"室内分布系统中，当需要延伸覆盖范围时，可引入的有源设备是？","options":[{"label":"A","content":"功分器"},{"label":"B","content":"耦合器"},{"label":"C","content":"干线放大器"},{"label":"D","content":"天线"}],"answer":"C","explanation":"干线放大器是有源设备，可补偿信号传输损耗，延伸覆盖范围；功分器、耦合器、天线均为无源器件，无放大功能，故C正确。","no":48},{"id":"1718790807029","type":"single","material":"","stem":"CDMA系统中，T_DROP参数的作用是？","options":[{"label":"A","content":"导频加入激活集的门限"},{"label":"B","content":"导频从激活集删除的门限"},{"label":"C","content":"激活集与候选集的比较门限"},{"label":"D","content":"导频删除定时器"}],"answer":"B","explanation":"T_DROP是导频从激活集删除的门限，当导频强度低于该值且持续T_TDROP时间后，将其从激活集删除；T_ADD是加入门限，T_COMP是比较门限，故B正确。","no":49},{"id":"1718790807030","type":"single","material":"","stem":"下列哪种衰落是由多径传播引起的？","options":[{"label":"A","content":"慢衰落"},{"label":"B","content":"阴影衰落"},{"label":"C","content":"瑞利衰落"},{"label":"D","content":"多普勒衰落"}],"answer":"C","explanation":"瑞利衰落又称快衰落，由多径信号叠加导致，信号幅度快速起伏；慢衰落和阴影衰落由障碍物遮挡引起，多普勒衰落由相对运动引起，故C正确。","no":50},{"id":"1718790807031","type":"single","material":"","stem":"CDMA系统中，Walsh码的数量为？","options":[{"label":"A","content":"32个"},{"label":"B","content":"64个"},{"label":"C","content":"128个"},{"label":"D","content":"256个"}],"answer":"B","explanation":"CDMA系统中常用的Walsh码为64阶，共64个，用于前向链路的正交调制和用户区分；高阶系统可能采用更高阶Walsh码，但基础为64个，故B正确。","no":51},{"id":"1718790807032","type":"single","material":"","stem":"基站天线的极化方式不包括？","options":[{"label":"A","content":"垂直极化"},{"label":"B","content":"水平极化"},{"label":"C","content":"双极化"},{"label":"D","content":"圆形极化"}],"answer":"D","explanation":"基站天线常见极化方式包括垂直极化、水平极化、双极化（垂直+水平）；圆形极化并非基站常用极化方式，故D正确。","no":52},{"id":"1718790807033","type":"single","material":"","stem":"CDMA系统中，周期登记的周期由哪个参数控制？","options":[{"label":"A","content":"REG_PRD"},{"label":"B","content":"T_ADD"},{"label":"C","content":"T_DROP"},{"label":"D","content":"MAX_SLOT_CYCLE_INDEX"}],"answer":"A","explanation":"REG_PRD是周期登记周期参数，控制移动台发起周期登记的时间间隔；MAX_SLOT_CYCLE_INDEX控制时隙周期指数，故A正确。","no":53},{"id":"1718790807034","type":"single","material":"","stem":"下列哪种干扰属于CDMA系统内部干扰？","options":[{"label":"A","content":"热噪声"},{"label":"B","content":"邻频干扰"},{"label":"C","content":"工业干扰"},{"label":"D","content":"天电干扰"}],"answer":"B","explanation":"邻频干扰是CDMA系统内相邻信道之间的干扰，属于内部干扰；热噪声是固有噪声，工业干扰、天电干扰属于外部干扰，故B正确。","no":54},{"id":"1718790807035","type":"single","material":"","stem":"CDMA前向业务信道的功率分配由基站根据什么动态调整？","options":[{"label":"A","content":"用户距离"},{"label":"B","content":"用户数量"},{"label":"C","content":"信道质量"},{"label":"D","content":"以上都是"}],"answer":"D","explanation":"前向业务信道功率由基站根据用户距离（路径损耗）、用户数量（干扰水平）、信道质量（误帧率）动态调整，确保每个用户的信号质量满足要求，故D正确。","no":55},{"id":"1718790807036","type":"single","material":"","stem":"室内分布系统中，馈线的选型应优先考虑？","options":[{"label":"A","content":"损耗小"},{"label":"B","content":"价格低"},{"label":"C","content":"易弯曲"},{"label":"D","content":"重量轻"}],"answer":"A","explanation":"馈线的核心指标是传输损耗，损耗小可减少信号衰减，保证覆盖质量；价格、弯曲性、重量是次要考虑因素，故A正确。","no":56},{"id":"1718790807037","type":"single","material":"","stem":"CDMA系统中，软切换的激活集最大数量通常为？","options":[{"label":"A","content":"2个"},{"label":"B","content":"3个"},{"label":"C","content":"4个"},{"label":"D","content":"5个"}],"answer":"C","explanation":"CDMA系统中，软切换的激活集最大数量通常为4个，最多支持4个基站同时为一个移动台提供服务，平衡切换质量和系统负荷，故C正确。","no":57},{"id":"1718790807038","type":"single","material":"","stem":"下列哪种KPI指标反映CDMA系统的通信保持能力？","options":[{"label":"A","content":"无线接通率"},{"label":"B","content":"业务信道掉话率"},{"label":"C","content":"寻呼成功率"},{"label":"D","content":"登记成功率"}],"answer":"B","explanation":"业务信道掉话率=业务信道掉话次数/业务信道占用次数，反映通信过程中保持连接的能力；接通率反映建立能力，寻呼成功率反映寻呼能力，故B正确。","no":58},{"id":"1718790807039","type":"single","material":"","stem":"CDMA系统中，反向功率控制的最大发射功率由哪个参数限制？","options":[{"label":"A","content":"INIT_PWR"},{"label":"B","content":"PWR_STEP"},{"label":"C","content":"MAX_TX_PWR"},{"label":"D","content":"NUM_STEP"}],"answer":"C","explanation":"MAX_TX_PWR是移动台反向最大发射功率参数，限制移动台的最高发射功率，避免过度干扰；INIT_PWR是初始功率偏置，PWR_STEP是功率增量，故C正确。","no":59},{"id":"1718790807040","type":"single","material":"","stem":"天馈系统中，天线方位角的调整主要影响？","options":[{"label":"A","content":"覆盖范围的方向"},{"label":"B","content":"覆盖范围的大小"},{"label":"C","content":"信号强度"},{"label":"D","content":"驻波比"}],"answer":"A","explanation":"天线方位角决定天线的辐射方向，调整方位角可改变覆盖范围的方向，使信号集中在目标区域；覆盖范围大小由功率、增益、下倾角决定，故A正确。","no":60},{"id":"1718790807041","type":"single","material":"","stem":"CDMA系统中，同步信道的帧长为？","options":[{"label":"A","content":"20ms"},{"label":"B","content":"40ms"},{"label":"C","content":"80ms"},{"label":"D","content":"160ms"}],"answer":"C","explanation":"CDMA同步信道的帧长为80ms，每帧传输固定的同步信息，移动台通过接收同步信道帧完成系统同步；业务信道帧长通常为20ms，故C正确。","no":61},{"id":"1718790807042","type":"single","material":"","stem":"下列哪种技术用于解决CDMA系统的导频污染？","options":[{"label":"A","content":"增大导频功率"},{"label":"B","content":"调整天线方位角和下倾角"},{"label":"C","content":"减小搜索窗"},{"label":"D","content":"降低软切换比例"}],"answer":"B","explanation":"解决导频污染的核心是形成主导频，可通过调整天线方位角和下倾角，增强目标导频强度，减弱干扰导频；增大导频功率可能加剧干扰，减小搜索窗会丢失多径，故B正确。","no":62},{"id":"1718790807043","type":"single","material":"","stem":"CDMA系统中，接入信道的前缀长度由哪个参数控制？","options":[{"label":"A","content":"PAM_SZ"},{"label":"B","content":"MAX_CAP_SZ"},{"label":"C","content":"INIT_PWR"},{"label":"D","content":"PWR_STEP"}],"answer":"A","explanation":"PAM_SZ是接入信道前缀长度参数，控制接入探针的前缀长度，影响接入信号的检测概率；MAX_CAP_SZ是最大接入消息长度，故A正确。","no":63},{"id":"1718790807044","type":"single","material":"","stem":"室内分布系统中，光功率计的主要用途是？","options":[{"label":"A","content":"测量光纤损耗"},{"label":"B","content":"测量天线口功率"},{"label":"C","content":"测量驻波比"},{"label":"D","content":"定位光纤故障"}],"answer":"B","explanation":"光功率计用于测量光信号的功率，在室内分布系统中可测量天线口、信源输出等光功率；测量光纤损耗和定位故障用OTDR，测量驻波比用驻波比测试仪，故B正确。","no":64},{"id":"1718790807045","type":"single","material":"","stem":"CDMA系统中，T_COMP参数的默认值通常为？","options":[{"label":"A","content":"3"},{"label":"B","content":"5"},{"label":"C","content":"8"},{"label":"D","content":"10"}],"answer":"B","explanation":"T_COMP是激活集与候选集的比较门限，默认值为5dB，当候选集导频强度比激活集最弱导频强度高T_COMP时，将其加入激活集，故B正确。","no":65},{"id":"1718790807046","type":"single","material":"","stem":"下列哪种衰落的变化频率低于10Hz？","options":[{"label":"A","content":"快衰落"},{"label":"B","content":"瑞利衰落"},{"label":"C","content":"慢衰落"},{"label":"D","content":"多径衰落"}],"answer":"C","explanation":"慢衰落的变化频率低于10Hz，属于长期变化；快衰落（瑞利衰落、多径衰落）的变化频率高于10Hz，属于短期快速变化，故C正确。","no":66},{"id":"1718790807047","type":"single","material":"","stem":"CDMA系统中，基站的CE（信道单元）主要用于？","options":[{"label":"A","content":"信号放大"},{"label":"B","content":"信道调制解调"},{"label":"C","content":"功率控制"},{"label":"D","content":"同步处理"}],"answer":"B","explanation":"CE是信道单元，用于CDMA信道的调制解调，决定基站支持的并发用户数（含软切换）；信号放大由功放完成，功率控制由基带处理单元完成，故B正确。","no":67},{"id":"1718790807048","type":"single","material":"","stem":"天馈系统中，当驻波比大于1.5时，可能导致的问题是？","options":[{"label":"A","content":"信号强度增强"},{"label":"B","content":"功率损耗增大"},{"label":"C","content":"干扰减小"},{"label":"D","content":"覆盖范围扩大"}],"answer":"B","explanation":"驻波比大于1.5时，反射波增强，信号传输的功率损耗增大，导致实际发射功率下降，覆盖范围缩小，干扰可能增大，故B正确。","no":68},{"id":"1718790807049","type":"single","material":"","stem":"CDMA系统中，位置登记的类型不包括？","options":[{"label":"A","content":"距离登记"},{"label":"B","content":"参数更新登记"},{"label":"C","content":"切换登记"},{"label":"D","content":"指令登记"}],"answer":"C","explanation":"位置登记类型包括开机登记、关机登记、周期登记、区域登记、距离登记、参数更新登记、指令登记等；切换登记并非独立登记类型，切换过程中可能伴随位置更新，故C正确。","no":69},{"id":"1718790807050","type":"single","material":"","stem":"1XEV-DO系统中，前向链路的调度算法主要基于？","options":[{"label":"A","content":"用户优先级"},{"label":"B","content":"信道质量"},{"label":"C","content":"用户请求"},{"label":"D","content":"业务类型"}],"answer":"B","explanation":"1XEV-DO前向链路采用基于信道质量的调度算法，优先为信道质量好的用户分配资源，提高系统吞吐量；用户优先级和业务类型是辅助调度因素，故B正确。","no":70},{"id":"1718790807051","type":"single","material":"","stem":"CDMA系统中，反向链路的主要干扰来源是？","options":[{"label":"A","content":"同频基站"},{"label":"B","content":"邻频基站"},{"label":"C","content":"本小区和邻小区用户"},{"label":"D","content":"外部噪声"}],"answer":"C","explanation":"CDMA反向链路是干扰受限链路，主要干扰来源是本小区和邻小区的其他用户，每个用户的信号对其他用户都是干扰；基站干扰主要影响前向链路，故C正确。","no":71},{"id":"1718790807052","type":"single","material":"","stem":"室内分布系统中，当信源为直放站时，需重点控制的是？","options":[{"label":"A","content":"发射功率"},{"label":"B","content":"引入噪声"},{"label":"C","content":"覆盖范围"},{"label":"D","content":"天线数量"}],"answer":"B","explanation":"直放站是有源设备，会引入额外噪声，干扰施主基站的反向链路，需控制上行增益，确保引入噪声不超过基站底噪升高阈值（通常≤3dB），故B正确。","no":72},{"id":"1718790807053","type":"single","material":"","stem":"CDMA系统中，寻呼信道的负荷过高时，可采取的优化措施是？","options":[{"label":"A","content":"增加寻呼信道数量"},{"label":"B","content":"减小LAC范围"},{"label":"C","content":"优化登记周期"},{"label":"D","content":"以上都是"}],"answer":"D","explanation":"寻呼信道负荷过高时，可通过增加寻呼信道数量、减小LAC范围（减少单LAC寻呼量）、优化登记周期（减少登记信令）等措施缓解，故D正确。","no":73},{"id":"1718790807054","type":"single","material":"","stem":"基站天线的水平半功率角用于描述？","options":[{"label":"A","content":"垂直方向的覆盖范围"},{"label":"B","content":"水平方向的覆盖范围"},{"label":"C","content":"天线增益"},{"label":"D","content":"极化方式"}],"answer":"B","explanation":"水平半功率角是天线水平方向图中，功率下降3dB时的夹角，描述水平方向的覆盖范围；垂直半功率角描述垂直方向覆盖范围，故B正确。","no":74},{"id":"1718790807055","type":"single","material":"","stem":"CDMA系统中，当移动台处于空闲态时，主要监听的信道是？","options":[{"label":"A","content":"导频信道和寻呼信道"},{"label":"B","content":"同步信道和业务信道"},{"label":"C","content":"接入信道和反向导频信道"},{"label":"D","content":"前向业务信道和寻呼信道"}],"answer":"A","explanation":"移动台空闲态时，持续监听导频信道（保持同步）和寻呼信道（接收寻呼消息）；同步信道仅在初始化时监听，业务信道在通话时使用，故A正确。","no":75},{"id":"1718790807056","type":"single","material":"","stem":"下列哪种技术不属于CDMA的功率控制技术？","options":[{"label":"A","content":"开环功率控制"},{"label":"B","content":"闭环功率控制"},{"label":"C","content":"外环功率控制"},{"label":"D","content":"频率功率控制"}],"answer":"D","explanation":"CDMA功率控制包括开环（反向初始功率调整）、闭环（内环+外环，动态调整）；频率功率控制并非CDMA的功率控制类型，故D正确。","no":76},{"id":"1718790807057","type":"single","material":"","stem":"室内分布系统中，光纤直放站的优点是？","options":[{"label":"A","content":"无传输损耗"},{"label":"B","content":"引入噪声小"},{"label":"C","content":"覆盖范围广"},{"label":"D","content":"无需施主基站"}],"answer":"B","explanation":"光纤直放站通过光纤传输施主基站信号，传输损耗小，引入噪声比无线直放站小，对施主基站干扰小；光纤仍有轻微损耗，需依赖施主基站，故B正确。","no":77},{"id":"1718790807058","type":"single","material":"","stem":"CDMA系统中，业务信道掉话率的优化目标通常为？","options":[{"label":"A","content":"≤0.55%"},{"label":"B","content":"≤1%"},{"label":"C","content":"≤2%"},{"label":"D","content":"≤5%"}],"answer":"A","explanation":"CDMA系统中，业务信道掉话率的优化目标通常为≤0.55%，反映网络通信保持质量的核心指标；不同运营商可能有细微差异，但主流目标为0.55%，故A正确。","no":78},{"id":"1718790807059","type":"single","material":"","stem":"天馈系统中，接地装置的主要作用是？","options":[{"label":"A","content":"增强信号强度"},{"label":"B","content":"防止雷击损坏设备"},{"label":"C","content":"降低驻波比"},{"label":"D","content":"过滤干扰"}],"answer":"B","explanation":"天馈系统的接地装置用于将雷电感应的电荷导入大地，防止雷击损坏天线、馈线和基站设备；增强信号强度需调整天线或功率，故B正确。","no":79},{"id":"1718790807060","type":"single","material":"","stem":"CDMA系统中，当用户从CDMA1X网络切换到1XEV-DO网络时，属于哪种切换？","options":[{"label":"A","content":"软切换"},{"label":"B","content":"硬切换"},{"label":"C","content":"跨系统切换"},{"label":"D","content":"虚拟切换"}],"answer":"C","explanation":"CDMA1X和1XEV-DO属于不同的业务网络，二者间的切换属于跨系统切换；软切换和虚拟切换适用于同系统同频场景，故C正确。","no":80},{"id":"1718790807061","type":"single","material":"","stem":"第五代移动通信技术（5G）的核心性能目标不包括以下哪项？","options":[{"label":"A","content":"高数据速率"},{"label":"B","content":"增加网络延迟"},{"label":"C","content":"节省能源"},{"label":"D","content":"大规模设备连接"}],"answer":"B","explanation":"5G的核心性能目标包括高数据速率、减少延迟（而非增加）、节省能源、降低成本、提高系统容量和大规模设备连接；延迟增加会影响实时应用（如自动驾驶），不符合5G设计初衷，故B正确。","no":81},{"id":"1718790807062","type":"single","material":"","stem":"5G网络的理论峰值数据传输速率最高可达多少？","options":[{"label":"A","content":"1Gbit/s"},{"label":"B","content":"10Gbit/s"},{"label":"C","content":"20Gbit/s"},{"label":"D","content":"500Mbit/s"}],"answer":"B","explanation":"5G网络的理论峰值速率最高可达10Gbit/s，比4GLTE快100倍；20Gbit/s是ITUIMT-2020规范的远期目标，1Gbit/s是早期5G测试速率，500Mbit/s是用户体验速率相关指标，故B正确。","no":82},{"id":"1718790807063","type":"single","material":"","stem":"5G网络的空中接口时延水平通常要求在什么范围？","options":[{"label":"A","content":"1ms左右"},{"label":"B","content":"30-70ms"},{"label":"C","content":"100ms左右"},{"label":"D","content":"1s以内"}],"answer":"A","explanation":"5G为满足自动驾驶、远程医疗等实时应用，空中接口时延需控制在1ms左右；30-70ms是4G网络的典型时延，100ms及1s均无法满足5G实时业务需求，故A正确。","no":83},{"id":"1718790807064","type":"single","material":"","stem":"国际电信联盟（ITU）对5G的规范要求中，速度目标高达多少？","options":[{"label":"A","content":"10Gbit/s"},{"label":"B","content":"15Gbit/s"},{"label":"C","content":"20Gbit/s"},{"label":"D","content":"25Gbit/s"}],"answer":"C","explanation":"ITUIMT-2020规范对5G的速度要求高达20Gbit/s，可实现宽信道带宽和大容量MIMO；10Gbit/s是5G商用初期的理论峰值，15Gbit/s、25Gbit/s并非ITU规范的正式目标，故C正确。","no":84},{"id":"1718790807065","type":"single","material":"","stem":"中国正式发放5G商用牌照的时间是？","options":[{"label":"A","content":"2018年12月"},{"label":"B","content":"2019年6月6日"},{"label":"C","content":"2019年10月31日"},{"label":"D","content":"2020年4月"}],"answer":"B","explanation":"2019年6月6日，工信部正式向中国电信、中国移动、中国联通、中国广电发放5G商用牌照，标志中国进入5G商用元年；2018年12月是5G试验频率发放时间，2019年10月31日是5G商用套餐上线时间，2020年4月是Release-16规范完成时间，故B正确。","no":85},{"id":"1718790807066","type":"single","material":"","stem":"全球首个实现5G商用服务的国家是？","options":[{"label":"A","content":"中国"},{"label":"B","content":"韩国"},{"label":"C","content":"美国"},{"label":"D","content":"日本"}],"answer":"B","explanation":"2018年12月1日，韩国三大运营商SK、KT与LGU+同步在韩国部分地区推出5G服务，是全球首个实现5G商用的国家；中国2019年商用，美国2018年12月下旬商用，日本尚未率先商用，故B正确。","no":86},{"id":"1718790807067","type":"single","material":"","stem":"5G标准的主要制定组织是？","options":[{"label":"A","content":"IEEE"},{"label":"B","content":"3GPP"},{"label":"C","content":"ISO"},{"label":"D","content":"IETF"}],"answer":"B","explanation":"3GPP是5G标准的核心制定组织，完成了5GNR（新无线）的独立组网（SA）和非独立组网（NSA）标准冻结；IEEE主要制定Wi-Fi等标准，ISO是国际标准化组织，IETF专注互联网协议标准，故B正确。","no":87},{"id":"1718790807068","type":"single","material":"","stem":"5GNR独立组网（SA）方案正式冻结并发布的时间是？","options":[{"label":"A","content":"2017年12月"},{"label":"B","content":"2018年6月"},{"label":"C","content":"2019年6月"},{"label":"D","content":"2020年4月"}],"answer":"B","explanation":"2018年6月，3GPP第80次TSGRAN全会正式完成并发布5GNR独立组网（SA）方案，标志首个完整意义的国际5G标准出炉；2017年12月完成的是非独立组网（NSA）标准，故B正确。","no":88},{"id":"1718790807069","type":"single","material":"","stem":"5G网络中，为支持千倍流量增长的核心技术之一是？","options":[{"label":"A","content":"超密集异构网络"},{"label":"B","content":"光纤入户技术"},{"label":"C","content":"蓝牙通信技术"},{"label":"D","content":"红外传输技术"}],"answer":"A","explanation":"超密集异构网络通过减小小区半径、增加低功率节点数量，是保证5G支持千倍流量增长的核心技术；光纤入户是固定网络技术，蓝牙、红外传输速率低，无法支撑5G大流量需求，故A正确。","no":89},{"id":"1718790807070","type":"single","material":"","stem":"设备到设备直接通信技术的英文缩写是？","options":[{"label":"A","content":"M2M"},{"label":"B","content":"D2D"},{"label":"C","content":"ICN"},{"label":"D","content":"CDN"}],"answer":"B","explanation":"D2D（device-to-device communication）是5G中的设备到设备直接通信技术，数据直接在终端间传输，无需基站转发；M2M是机器对机器通信，ICN是信息中心网络，CDN是内容分发网络，故B正确。","no":90},{"id":"1718790807071","type":"single","material":"","stem":"5G中频频谱的核心频段不包括以下哪个范围？","options":[{"label":"A","content":"3300-3600MHz"},{"label":"B","content":"4800-5000MHz"},{"label":"C","content":"28GHz"},{"label":"D","content":"3500-3600MHz"}],"answer":"C","explanation":"中国工信部确定的5G中频频段包括3300-3600MHz、4800-5000MHz、3500-3600MHz（试验频段）；28GHz属于超高频段（mmWave），并非中频频段，故C正确。","no":91},{"id":"1718790807072","type":"single","material":"","stem":"5G技术中，能够实现用户就近获取内容、降低网络时延的技术是？","options":[{"label":"A","content":"自组织网络（SON）"},{"label":"B","content":"内容分发网络（CDN）"},{"label":"C","content":"信息中心网络（ICN）"},{"label":"D","content":"M2M通信"}],"answer":"B","explanation":"CDN通过将内容分发至靠近用户的代理服务器，实现用户就近获取信息，缓解网络拥塞、降低时延；SON侧重网络自规划自优化，ICN以信息为中心传输，M2M是物联网通信形式，故B正确。","no":92},{"id":"1718790807073","type":"single","material":"","stem":"5G网络中，支持千亿设备连接能力的核心目标是为了满足什么需求？","options":[{"label":"A","content":"高清视频传输"},{"label":"B","content":"虚拟现实应用"},{"label":"C","content":"物联网通信"},{"label":"D","content":"远程医疗"}],"answer":"C","explanation":"5G的超大网络容量（千亿设备连接）主要针对物联网通信需求，支持海量终端（如智能家电、传感器）接入；高清视频、虚拟现实依赖高数据速率，远程医疗依赖低时延，故C正确。","no":93},{"id":"1718790807074","type":"single","material":"","stem":"5G非独立组网（NSA）的核心特点是？","options":[{"label":"A","content":"不依赖4G核心网"},{"label":"B","content":"依赖4G核心网和基站"},{"label":"C","content":"完全独立部署网络"},{"label":"D","content":"仅支持低速物联网业务"}],"answer":"B","explanation":"NSA（非独立组网）是5G初期部署模式，依赖4G核心网和基站提供控制信令和部分数据传输；SA（独立组网）不依赖4G网络，可完全独立部署，NSA也支持高速业务，故B正确。","no":94},{"id":"1718790807075","type":"single","material":"","stem":"5GRelease-16规范完成的时间是？","options":[{"label":"A","content":"2017年12月"},{"label":"B","content":"2018年6月"},{"label":"C","content":"2020年4月"},{"label":"D","content":"2019年6月"}],"answer":"C","explanation":"5GRelease-16规范于2020年4月完成，作为IMT-2020技术候选提交给ITU；2017年12月完成Release-15NSA版本，2018年6月完成Release-15SA版本，故C正确。","no":95},{"id":"1718790807076","type":"single","material":"","stem":"5G网络的频谱效率相比4GLTE需要提升多少倍以上？","options":[{"label":"A","content":"5倍"},{"label":"B","content":"10倍"},{"label":"C","content":"15倍"},{"label":"D","content":"20倍"}],"answer":"B","explanation":"5G的关键性能要求之一是频谱效率比LTE提升10倍以上，通过大规模MIMO、超密集组网等技术实现；5倍、15倍、20倍均不符合5G的正式性能指标，故B正确。","no":96},{"id":"1718790807077","type":"single","material":"","stem":"以下哪项是5G在医疗领域的典型应用？","options":[{"label":"A","content":"智能电网监测"},{"label":"B","content":"远程外科手术"},{"label":"C","content":"自动驾驶"},{"label":"D","content":"车联网通信"}],"answer":"B","explanation":"5G低时延特性支持远程外科手术，2019年已实现全球首例5G远程手术；智能电网是能源领域应用，自动驾驶、车联网是交通领域应用，故B正确。","no":97},{"id":"1718790807078","type":"single","material":"","stem":"自组织网络（SON）在5G中的核心作用不包括？","options":[{"label":"A","content":"网络自规划"},{"label":"B","content":"网络自配置"},{"label":"C","content":"人工优化网络参数"},{"label":"D","content":"网络自愈合"}],"answer":"C","explanation":"SON的核心作用包括网络部署阶段的自规划、自配置，以及维护阶段的自优化、自愈合，可减少人工干预；人工优化网络参数是传统网络的做法，并非SON的作用，故C正确。","no":98},{"id":"1718790807079","type":"single","material":"","stem":"5G用户在连续广域覆盖和高移动性下的体验速率目标是？","options":[{"label":"A","content":"10Mbit/s"},{"label":"B","content":"100Mbit/s"},{"label":"C","content":"1Gbit/s"},{"label":"D","content":"10Gbit/s"}],"answer":"B","explanation":"5G在连续广域覆盖和高移动性场景下，用户体验速率需达到100Mbit/s，满足日常高速数据传输需求；10Mbit/s是4G体验速率，1Gbit/s是峰值体验速率，10Gbit/s是理论峰值速率，故B正确。","no":99},{"id":"1718790807080","type":"single","material":"","stem":"5G中，机器对机器通信（M2M）的广义定义不包括以下哪类通信？","options":[{"label":"A","content":"机器对机器"},{"label":"B","content":"人与机器间"},{"label":"C","content":"移动网络与机器间"},{"label":"D","content":"人与人之间"}],"answer":"D","explanation":"广义M2M涵盖机器对机器、人与机器间、移动网络与机器间的通信；人与人之间的通信是传统移动通信的核心，不属于M2M的定义范畴，故D正确。","no":100},{"id":"1718790807081","type":"single","material":"","stem":"中国三大运营商正式上线5G商用套餐的时间是？","options":[{"label":"A","content":"2019年6月6日"},{"label":"B","content":"2019年10月31日"},{"label":"C","content":"2019年11月1日"},{"label":"D","content":"2020年4月"}],"answer":"C","explanation":"2019年10月31日三大运营商公布5G商用套餐，11月1日正式上线执行；2019年6月6日是商用牌照发放时间，2020年4月是Release-16规范完成时间，故C正确。","no":101},{"id":"1718790807082","type":"single","material":"","stem":"5G信息中心网络（ICN）采用的传输模式是？","options":[{"label":"A","content":"“推”模式"},{"label":"B","content":"“拉”模式"},{"label":"C","content":"仅广播模式"},{"label":"D","content":"仅组播模式"}],"answer":"B","explanation":"ICN采用“拉”模式，由用户实时信息请求触发传输，网络通过缓存快速响应；传统IP网络采用“推”模式，服务器主导传输；ICN支持多播传递，但核心模式是“拉”模式，故B正确。","no":102},{"id":"1718790807083","type":"single","material":"","stem":"以下哪项不属于5G的关键技术？","options":[{"label":"A","content":"大规模MIMO"},{"label":"B","content":"超密集异构网络"},{"label":"C","content":"时分多址（TDMA）"},{"label":"D","content":"D2D通信"}],"answer":"C","explanation":"5G的关键技术包括大规模MIMO、超密集异构网络、D2D通信、SON等；TDMA是2G/3G时代的多址技术，5G主要采用正交频分多址（OFDMA），故C正确。","no":103},{"id":"1718790807084","type":"single","material":"","stem":"5G网络中，相邻节点密集部署导致的主要问题是？","options":[{"label":"A","content":"覆盖范围过小"},{"label":"B","content":"网络干扰加剧"},{"label":"C","content":"传输速率下降"},{"label":"D","content":"终端功耗增加"}],"answer":"B","explanation":"超密集异构网络中，节点间距离减小导致网络拓扑复杂，同频干扰、共享频谱干扰等问题加剧，需通过干扰协调算法解决；密集部署可扩大覆盖、提升速率，与终端功耗无直接关联，故B正确。","no":104},{"id":"1718790807085","type":"single","material":"","stem":"5G在车联网领域的应用目标是实现什么？","options":[{"label":"A","content":"仅车辆导航"},{"label":"B","content":"车辆间语音通信"},{"label":"C","content":"全面自动驾驶"},{"label":"D","content":"仅车辆状态监测"}],"answer":"C","explanation":"依托5G高速率、低时延特性，车联网的发展目标是2025年全面实现自动驾驶量产；导航、语音通信、状态监测是4G车联网的功能，故C正确。","no":105},{"id":"1718790807086","type":"single","material":"","stem":"5G商用初期，华为发布的首款3GPP标准5G商用芯片是？","options":[{"label":"A","content":"巴龙5G01"},{"label":"B","content":"骁龙X55"},{"label":"C","content":"天玑1000"},{"label":"D","content":"麒麟9905G"}],"answer":"A","explanation":"2018年MWC展上，华为发布首款3GPP标准5G商用芯片巴龙5G01；骁龙X55是高通芯片，天玑1000是联发科芯片，麒麟9905G是手机集成芯片，故A正确。","no":106},{"id":"1718790807087","type":"single","material":"","stem":"5G网络中，D2D通信的数据传输特点是？","options":[{"label":"A","content":"必须通过基站转发"},{"label":"B","content":"直接在终端间传输"},{"label":"C","content":"仅支持授权频段部署"},{"label":"D","content":"会增加基站负担"}],"answer":"B","explanation":"D2D通信的核心是终端间直接传输数据，无需基站转发，仅控制信令由蜂窝网络负责；可在授权或非授权频段部署，能减轻基站负担，故B正确。","no":107},{"id":"1718790807088","type":"single","material":"","stem":"国际电信联盟（ITU）对5G的技术命名是？","options":[{"label":"A","content":"IMT-2010"},{"label":"B","content":"IMT-2020"},{"label":"C","content":"IMT - Advanced"},{"label":"D","content":"IMT-2000"}],"answer":"B","explanation":"ITU将5G技术命名为IMT-2020，对应2020年完成标准提交；IMT-2010是4G，IMT -Advanced是4G增强版，IMT-2000是3G，故B正确。","no":108},{"id":"1718790807089","type":"single","material":"","stem":"5G网络中，流量密度和连接数密度的提升主要服务于什么场景？","options":[{"label":"A","content":"家庭宽带接入"},{"label":"B","content":"物联网大规模部署"},{"label":"C","content":"高清视频点播"},{"label":"D","content":"远程办公"}],"answer":"B","explanation":"流量密度和连接数密度的大幅提升是5G适配物联网大规模部署的关键，支持海量低功耗终端同时接入；家庭宽带、高清视频、远程办公主要依赖高数据速率，故B正确。","no":109},{"id":"1718790807090","type":"single","material":"","stem":"5G Release-15规范的第一阶段主要用于什么目的？","options":[{"label":"A","content":"支持自动驾驶"},{"label":"B","content":"适应早期商业部署"},{"label":"C","content":"实现千亿设备连接"},{"label":"D","content":"支持远程医疗"}],"answer":"B","explanation":"5GRelease-15规范第一阶段的核心目标是适应早期商业部署，重点满足增强移动宽带（e MBB）需求；自动驾驶、千亿设备连接、远程医疗需依赖后续Release-16及以上规范，故B正确。","no":110},{"id":"1718790807091","type":"single","material":"","stem":"以下哪个频段不属于中国5G试验或商用频段？","options":[{"label":"A","content":"3300-3600MHz"},{"label":"B","content":"4800-5000MHz"},{"label":"C","content":"2.4GHz"},{"label":"D","content":"3500-3600MHz"}],"answer":"C","explanation":"2.4GHz是Wi-Fi的常用频段，并非中国5G的试验或商用频段；3300-3600MHz、4800-5000MHz、3500-3600MHz均为中国5G明确的中频频段，故C正确。","no":111},{"id":"1718790807092","type":"single","material":"","stem":"5G自组织网络（SON）的自愈合功能是指？","options":[{"label":"A","content":"自动扩展网络覆盖"},{"label":"B","content":"自动检测并排除网络故障"},{"label":"C","content":"自动优化网络参数"},{"label":"D","content":"自动配置新增网络节点"}],"answer":"B","explanation":"SON的自愈合功能指系统能自动检测网络问题、定位故障并排除，减少维护成本；自动扩展覆盖是自规划功能，优化参数是自优化功能，配置新增节点是自配置功能，故B正确。","no":112},{"id":"1718790807093","type":"single","material":"","stem":"5G在智能电网领域的应用要求不包括？","options":[{"label":"A","content":"99.999%的高可靠度"},{"label":"B","content":"小于20ms的超低时延"},{"label":"C","content":"仅支持少量终端接入"},{"label":"D","content":"终端深度覆盖"}],"answer":"C","explanation":"智能电网要求5G支持超大数量末端设备同时接入，而非少量终端；99.999%高可靠度、小于20ms时延、终端深度覆盖均是其核心要求，故C正确。","no":113},{"id":"1718790807094","type":"single","material":"","stem":"5G网络中，大规模MIMO技术的主要作用是？","options":[{"label":"A","content":"减少终端数量"},{"label":"B","content":"提升频谱效率和系统容量"},{"label":"C","content":"降低网络部署成本"},{"label":"D","content":"仅支持单用户通信"}],"answer":"B","explanation":"大规模MIMO（多输入多输出）通过增加天线数量，可同时服务多个用户，显著提升频谱效率和系统容量；与终端数量无关，会增加部署成本，支持多用户通信，故B正确。","no":114},{"id":"1718790807095","type":"single","material":"","stem":"全球首个实现5G通话测试的合作双方是？","options":[{"label":"A","content":"沃达丰和华为"},{"label":"B","content":"中国移动和爱立信"},{"label":"C","content":"三星和NTT Do Co Mo"},{"label":"D","content":"中国联通和诺基亚"}],"answer":"A","explanation":"2018年2月，沃达丰和华为在西班牙合作，采用非独立的3GPP5G新无线标准和Sub6GHz频段完成全球首个5G通话测试；其他组合未实现首个5G通话测试，故A正确。","no":115},{"id":"1718790807096","type":"single","material":"","stem":"5G内容分发网络（CDN）的智能虚拟网络层次添加在什么之间？","options":[{"label":"A","content":"终端与基站"},{"label":"B","content":"基站与核心网"},{"label":"C","content":"用户侧与源服务器"},{"label":"D","content":"核心网与互联网"}],"answer":"C","explanation":"CDN在用户侧与源服务器之间添加智能虚拟网络层次，通过代理服务器分发内容；终端与基站、基站与核心网、核心网与互联网之间的层次不涉及CDN的核心部署，故C正确。","no":116},{"id":"1718790807097","type":"single","material":"","stem":"5G独立组网（SA）方案的优势不包括？","options":[{"label":"A","content":"完全独立于4G网络"},{"label":"B","content":"支持更低时延"},{"label":"C","content":"部署成本更低"},{"label":"D","content":"支持更多新业务"}],"answer":"C","explanation":"SA方案需独立部署5G核心网和基站，部署成本高于NSA；其优势包括独立于4G网络、支持更低时延、适配新业务（如自动驾驶），故C正确。","no":117},{"id":"1718790807098","type":"single","material":"","stem":"5G网络中，干扰协调的主要挑战是？","options":[{"label":"A","content":"单个干扰源强度过大"},{"label":"B","content":"多个干扰源强度相近"},{"label":"C","content":"干扰源数量过少"},{"label":"D","content":"干扰仅存在于授权频段"}],"answer":"B","explanation":"5G超密集组网中，相邻节点传输损耗差别小，导致多个干扰源强度相近，现有协调算法难以应对；单个干扰源是4G网络的干扰特点，干扰源数量多，且授权和非授权频段均可能存在干扰，故B正确。","no":118},{"id":"1718790807099","type":"single","material":"","stem":"以下哪项是5G增强移动宽带（e MBB）的典型应用？","options":[{"label":"A","content":"智能电表数据采集"},{"label":"B","content":"高清虚拟现实（VR）"},{"label":"C","content":"环境监测"},{"label":"D","content":"智能门锁控制"}],"answer":"B","explanation":"e MBB聚焦高数据速率需求，高清VR是典型应用；智能电表、环境监测、智能门锁均属于物联网（m MTC）应用，对速率要求较低，故B正确。","no":119},{"id":"1718790807100","type":"single","material":"","stem":"5G网络中，动态部署技术的研究重点是应对什么问题？","options":[{"label":"A","content":"终端功耗过高"},{"label":"B","content":"网络拓扑和干扰的动态变化"},{"label":"C","content":"频谱资源稀缺"},{"label":"D","content":"基站覆盖范围不足"}],"answer":"B","explanation":"5G超密集组网中，用户部署的节点开启/关闭具有突发性和随机性，导致网络拓扑和干扰大范围动态变化，动态部署技术需应对这一问题；终端功耗、频谱稀缺、覆盖不足均有其他专门技术解决，故B正确。","no":120},{"id":"1718790807101","type":"single","material":"","stem":"光纤的三层结构从内到外依次是？","options":[{"label":"A","content":"纤芯、包层、涂覆层"},{"label":"B","content":"包层、纤芯、涂覆层"},{"label":"C","content":"涂覆层、纤芯、包层"},{"label":"D","content":"纤芯、涂覆层、包层"}],"answer":"A","explanation":"光纤的核心传输结构由内向外分为纤芯（光信号传输核心）、包层（提供光约束，折射率低于纤芯）、涂覆层（保护光纤免受外部损伤），三者共同保障光信号稳定传输，故A正确。","no":121},{"id":"1718790807102","type":"single","material":"","stem":"光纤导光的核心物理原理是？","options":[{"label":"A","content":"光的折射"},{"label":"B","content":"光的全反射"},{"label":"C","content":"光的衍射"},{"label":"D","content":"光的散射"}],"answer":"B","explanation":"光纤利用光的全反射特性实现光信号长距离传输，需满足两个条件：纤芯折射率大于包层折射率，入射光角度在临界角范围内，故B正确。","no":122},{"id":"1718790807103","type":"single","material":"","stem":"数值孔径（NA）的正确计算公式是？","options":[{"label":"A","content":"NA=n₀sinθ_c=√(n₁²-n₂²)"},{"label":"B","content":"NA=n₁sinθ_c=√(n₂²-n₁²)"},{"label":"C","content":"NA=n₀cosθ_c=√(n₁-n₂)"},{"label":"D","content":"NA=n₁cosθ_c=√(n₂-n₁)"}],"answer":"A","explanation":"数值孔径反映光纤接收和传输光的能力，与入射媒质折射率n₀、临界角θ_c相关，核心公式为NA=n₀sinθ_c，结合全反射条件可推导得NA=√(n₁²-n₂²)（n₁为纤芯折射率，n₂为包层折射率），故A正确。","no":123},{"id":"1718790807104","type":"single","material":"","stem":"单模光纤实现单模传输的关键条件是？","options":[{"label":"A","content":"归一化频率V>2.405"},{"label":"B","content":"归一化频率V=2.405"},{"label":"C","content":"归一化频率V<2.405"},{"label":"D","content":"归一化频率V≥2.405"}],"answer":"C","explanation":"单模光纤仅允许基模（HE₁₁）传输，需满足归一化频率V<2.405，此时所有高阶模式均截止；V≥2.405时会出现多模传输，故C正确。","no":124},{"id":"1718790807105","type":"single","material":"","stem":"光纤色散中，由不同传输模式的时延差引起的是？","options":[{"label":"A","content":"材料色散"},{"label":"B","content":"波导色散"},{"label":"C","content":"模间色散"},{"label":"D","content":"色度色散"}],"answer":"C","explanation":"色散分为三类：模间色散（多模光纤中不同模式传输速度差异导致）、材料色散（光纤材料折射率随波长变化引起）、波导色散（光场分布随波长变化导致）；色度色散是材料色散与波导色散的统称，故C正确。","no":125},{"id":"1718790807106","type":"single","material":"","stem":"光纤通信中常用的三个低损耗窗口不包括？","options":[{"label":"A","content":"850nm"},{"label":"B","content":"1310nm"},{"label":"C","content":"1550nm"},{"label":"D","content":"1700nm"}],"answer":"D","explanation":"光纤的低损耗窗口为850nm（短波长窗口）、1310nm（零色散窗口）、1550nm（最低损耗窗口），1700nm并非常用低损耗窗口，故D正确。","no":126},{"id":"1718790807107","type":"single","material":"","stem":"半导体激光器（LD）的工作机理是？","options":[{"label":"A","content":"自发辐射"},{"label":"B","content":"受激辐射"},{"label":"C","content":"受激吸收"},{"label":"D","content":"非辐射跃迁"}],"answer":"B","explanation":"LD基于受激辐射工作，高能级电子在外来光激励下跃迁到低能级，释放与激励光同频、同相、同偏振的相干光，故B正确。","no":127},{"id":"1718790807108","type":"single","material":"","stem":"发光二极管（LED）的核心特点是？","options":[{"label":"A","content":"有阈值电流"},{"label":"B","content":"输出相干光"},{"label":"C","content":"无阈值，自发辐射"},{"label":"D","content":"需温控电路"}],"answer":"C","explanation":"LED是无阈值发光器件，基于自发辐射发光，输出非相干光，温度特性较好，无需温控电路；LD有阈值电流，输出相干光，温度稳定性差，需温控，故C正确。","no":128},{"id":"1718790807109","type":"single","material":"","stem":"下列光检测器中，具有雪崩倍增效应的是？","options":[{"label":"A","content":"PIN光电二极管"},{"label":"B","content":"APD雪崩光电二极管"},{"label":"C","content":"光电三极管"},{"label":"D","content":"光敏电阻"}],"answer":"B","explanation":"APD通过外加高反向偏压在耗尽区形成强电场，使光生载流子碰撞电离产生雪崩倍增效应，大幅提高检测灵敏度；PIN光电二极管无倍增效应，故B正确。","no":129},{"id":"1718790807110","type":"single","material":"","stem":"光隔离器的工作原理基于？","options":[{"label":"A","content":"电光效应"},{"label":"B","content":"法拉第效应"},{"label":"C","content":"声光效应"},{"label":"D","content":"磁光效应"}],"answer":"B","explanation":"光隔离器是单向传输器件，利用晶体的非互易旋光性（法拉第效应），只允许光信号正向传输，抑制反向反射光对光源的影响，故B正确。","no":130},{"id":"1718790807111","type":"single","material":"","stem":"光发射机的核心组成部分不包括？","options":[{"label":"A","content":"光源"},{"label":"B","content":"驱动器"},{"label":"C","content":"光检测器"},{"label":"D","content":"调制器"}],"answer":"C","explanation":"光发射机负责电/光转换，核心组成包括光源（LD/LED）、驱动器（提供驱动电流）、调制器（实现光强度调制）；光检测器是光接收机的核心部件，故C正确。","no":131},{"id":"1718790807112","type":"single","material":"","stem":"光接收机中，用于低噪声放大微弱电信号的是？","options":[{"label":"A","content":"主放大器"},{"label":"B","content":"前置放大器"},{"label":"C","content":"均衡器"},{"label":"D","content":"判决器"}],"answer":"B","explanation":"光接收机的前置放大器需具备低噪声特性，放大光检测器输出的微弱电信号；主放大器提供足够增益，均衡器补偿信号畸变，判决器恢复数字信号，故B正确。","no":132},{"id":"1718790807113","type":"single","material":"","stem":"SDH同步传输模块STM-1的标准传输速率是？","options":[{"label":"A","content":"622Mbps"},{"label":"B","content":"155Mbps"},{"label":"C","content":"2.5Gbps"},{"label":"D","content":"10Gbps"}],"answer":"B","explanation":"SDH标准速率等级中，STM-1为155Mbps，STM-4为622Mbps，STM-16为2.5Gbps，STM-64为10Gbps，故B正确。","no":133},{"id":"1718790807114","type":"single","material":"","stem":"SDH信号的复用过程不包括以下哪个步骤？","options":[{"label":"A","content":"映射"},{"label":"B","content":"编码"},{"label":"C","content":"定位"},{"label":"D","content":"复用"}],"answer":"B","explanation":"SDH复用分为三个核心步骤：映射（支路信号适配进虚容器）、定位（通过指针指示虚容器位置）、复用（将复用单元组合为STM-N信号），编码不属于复用过程，故B正确。","no":134},{"id":"1718790807115","type":"single","material":"","stem":"密集波分复用（DWDM）的波长间隔通常为？","options":[{"label":"A","content":"1~10nm"},{"label":"B","content":"10~100nm"},{"label":"C","content":"<1nm"},{"label":"D","content":"100~200nm"}],"answer":"A","explanation":"WDM按波长间隔分类：CWDM（稀疏波分，间隔10~100nm）、DWDM（密集波分，间隔1~10nm）、OFDM（超密集波分，间隔<1nm），故A正确。","no":135},{"id":"1718790807116","type":"single","material":"","stem":"掺铒光纤放大器（EDFA）的工作波长范围是？","options":[{"label":"A","content":"850~900nm"},{"label":"B","content":"1310~1360nm"},{"label":"C","content":"1530~1560nm"},{"label":"D","content":"1600~1650nm"}],"answer":"C","explanation":"EDFA基于掺铒光纤的受激辐射实现信号放大，工作波长集中在1530~1560nm，与光纤1550nm低损耗窗口匹配，是长距离传输的核心器件，故C正确。","no":136},{"id":"1718790807117","type":"single","material":"","stem":"无源光网络（PON）的核心组成不包括？","options":[{"label":"A","content":"光线路终端（OLT）"},{"label":"B","content":"光配线网（ODN）"},{"label":"C","content":"光网络单元（ONU）"},{"label":"D","content":"光放大器（EDFA）"}],"answer":"D","explanation":"PON由OLT（网络侧接口，连接核心网）、ODN（无源传输链路，含光分路器）、ONU（用户侧接口，连接终端）组成，无需有源放大器，故D正确。","no":137},{"id":"1718790807118","type":"single","material":"","stem":"以太无源光网络（EPON）遵循的标准是？","options":[{"label":"A","content":"IEEE802.3"},{"label":"B","content":"IEEE802.3ah"},{"label":"C","content":"ITU-TG.984"},{"label":"D","content":"ITU-TG.652"}],"answer":"B","explanation":"EPON是基于以太网的PON技术，标准为IEEE802.3ah；ITU-TG.984是APON（ATM-PON）标准，ITU-TG.652是常规单模光纤标准，故B正确。","no":138},{"id":"1718790807119","type":"single","material":"","stem":"用于测量光纤损耗和故障定位的仪器是？","options":[{"label":"A","content":"光功率计"},{"label":"B","content":"误码测量仪"},{"label":"C","content":"光时域反射仪（OTDR）"},{"label":"D","content":"光谱分析仪"}],"answer":"C","explanation":"OTDR利用光信号传输中的瑞利散射和菲涅尔反射，可测量光纤损耗系数、故障点位置、光纤长度；光功率计仅测量光功率，误码仪测量传输误码率，故C正确。","no":139},{"id":"1718790807120","type":"single","material":"","stem":"光纤色散系数的单位是？","options":[{"label":"A","content":"dB/km"},{"label":"B","content":"ps/(nm・km)"},{"label":"C","content":"nm"},{"label":"D","content":"dB"}],"answer":"B","explanation":"色散系数D表示单位波长间隔的光信号经单位距离传输后的时延差，单位为ps/(nm・km)；dB/km是损耗系数单位，故B正确。","no":140},{"id":"1718790807121","type":"single","material":"","stem":"光纤损耗系数的单位是？","options":[{"label":"A","content":"ps/(nm・km)"},{"label":"B","content":"dB"},{"label":"C","content":"dB/km"},{"label":"D","content":"nm"}],"answer":"C","explanation":"损耗系数α表示单位距离光信号的衰减程度，单位为dB/km；ps/(nm・km)是色散系数单位，dB是衰减的绝对单位，故C正确。","no":141},{"id":"1718790807122","type":"single","material":"","stem":"SDH帧结构中，STM-1的总字节数是？","options":[{"label":"A","content":"2430字节"},{"label":"B","content":"19440字节"},{"label":"C","content":"9×270字节"},{"label":"D","content":"270×N字节"}],"answer":"A","explanation":"STM-1帧结构为9行×270列的块状帧，总字节数=9×270=2430字节；19440是总比特数（2430×8），270×N字节是STM-N的帧结构，故A正确。","no":142},{"id":"1718790807123","type":"single","material":"","stem":"光耦合器的核心功能是？","options":[{"label":"A","content":"光信号放大"},{"label":"B","content":"光信号分路或合路"},{"label":"C","content":"光信号隔离"},{"label":"D","content":"光信号调制"}],"answer":"B","explanation":"光耦合器是无源器件，核心功能是将光信号分路、合路或分配到多个光路，实现多用户或多业务传输；光放大由EDFA完成，光隔离由光隔离器完成，故B正确。","no":143},{"id":"1718790807124","type":"single","material":"","stem":"马赫-曾德尔（M-Z）干涉型调制器的工作原理基于？","options":[{"label":"A","content":"电光效应"},{"label":"B","content":"声光效应"},{"label":"C","content":"磁光效应"},{"label":"D","content":"法拉第效应"}],"answer":"A","explanation":"M-Z调制器利用铌酸锂晶体的电光效应，通过电信号控制光信号的相位差，进而实现光强度调制，是高速光通信中的常用调制器件，故A正确。","no":144},{"id":"1718790807125","type":"single","material":"","stem":"模拟光纤通信中的副载波复用（SCM）技术，其主调制方式是？","options":[{"label":"A","content":"光强调制"},{"label":"B","content":"相位调制"},{"label":"C","content":"频率调制"},{"label":"D","content":"幅度调制"}],"answer":"A","explanation":"SCM技术的实现过程为：先将模拟基带信号调制到射频载波（预调制），再用该复合电信号对光源进行光强调制（主调制），广泛应用于有线电视HFC网络，故A正确。","no":145},{"id":"1718790807126","type":"single","material":"","stem":"光孤子能长距离不变形传输的核心原因是？","options":[{"label":"A","content":"无色散"},{"label":"B","content":"无损耗"},{"label":"C","content":"非线性与色散平衡"},{"label":"D","content":"全反射增强"}],"answer":"C","explanation":"光孤子是超短光脉冲，在光纤反常色散区，折射率非线性（自相位调制）导致的脉冲压缩与群速色散导致的脉冲展宽相互平衡，使脉冲形状、幅度、速度保持不变，故C正确。","no":146},{"id":"1718790807127","type":"single","material":"","stem":"相干光通信的相干条件不包括？","options":[{"label":"A","content":"振动方向相同"},{"label":"B","content":"振动频率相同"},{"label":"C","content":"相位差恒定"},{"label":"D","content":"光功率相同"}],"answer":"D","explanation":"两束光实现相干需满足三个条件：振动方向相同、振动频率相同、相位差恒定，与光功率大小无关，故D正确。","no":147},{"id":"1718790807128","type":"single","material":"","stem":"光交换技术中，基于时隙互换实现信号交换的是？","options":[{"label":"A","content":"空分光交换"},{"label":"B","content":"时分光交换"},{"label":"C","content":"波分光交换"},{"label":"D","content":"码分光交换"}],"answer":"B","explanation":"时分光交换以时分复用为基础，通过时隙互换调整信号在时域的位置，实现不同用户或业务的信号交换；空分光交换改变空间传输路径，波分光交换基于波长选择，故B正确。","no":148},{"id":"1718790807129","type":"single","material":"","stem":"光纤光栅的核心特征是？","options":[{"label":"A","content":"纤芯折射率周期性变化"},{"label":"B","content":"包层折射率周期性变化"},{"label":"C","content":"涂覆层折射率周期性变化"},{"label":"D","content":"全反射增强"}],"answer":"A","explanation":"光纤光栅是通过特殊工艺使纤芯折射率产生永久周期性微扰形成的无源器件，实质是窄带滤光器或反射镜，可实现波长选择、色散补偿等功能，故A正确。","no":149},{"id":"1718790807130","type":"single","material":"","stem":"G.652光纤属于？","options":[{"label":"A","content":"色散移位光纤"},{"label":"B","content":"非零色散移位光纤"},{"label":"C","content":"常规单模光纤"},{"label":"D","content":"低损耗光纤"}],"answer":"C","explanation":"G.652光纤是常规单模光纤（STD），适用于1310nm和1550nm双窗口传输，是应用最广泛的单模光纤；G.653是色散移位光纤，G.655是非零色散移位光纤，故C正确。","no":150},{"id":"1718790807131","type":"single","material":"","stem":"G.655光纤的核心特点是？","options":[{"label":"A","content":"零色散在1310nm"},{"label":"B","content":"非零色散移位"},{"label":"C","content":"低损耗在850nm"},{"label":"D","content":"多模传输"}],"answer":"B","explanation":"G.655光纤是非零色散移位光纤（NZ-DSF），将零色散点移位至1550nm窗口且保持非零色散，避免DWDM系统中的四波混频效应，故B正确。","no":151},{"id":"1718790807132","type":"single","material":"","stem":"光发射机的直接调制方式会引入的问题是？","options":[{"label":"A","content":"功率衰减"},{"label":"B","content":"频率啁啾"},{"label":"C","content":"噪声增大"},{"label":"D","content":"色散加剧"}],"answer":"B","explanation":"直接调制通过控制光源驱动电流实现光强度调制，会导致光脉冲的载频随时间变化（频率啁啾），造成信号畸变；间接调制可避免该问题，故B正确。","no":152},{"id":"1718790807133","type":"single","material":"","stem":"光接收机的噪声主要来源不包括？","options":[{"label":"A","content":"热噪声"},{"label":"B","content":"散弹噪声"},{"label":"C","content":"雪崩噪声（APD）"},{"label":"D","content":"色散噪声"}],"answer":"D","explanation":"光接收机的噪声主要包括热噪声（放大器电阻产生）、散弹噪声（光检测器光生载流子随机起伏）、APD倍增噪声（雪崩倍增过程的随机性）；色散噪声是信号传输中的畸变，不属于接收机噪声，故D正确。","no":153},{"id":"1718790807134","type":"single","material":"","stem":"SDH网元中，用于在传输链路中途分接或插入低速信号的是？","options":[{"label":"A","content":"终端复用器（TM）"},{"label":"B","content":"分插复用器（ADM）"},{"label":"C","content":"再生中继器（REG）"},{"label":"D","content":"数字交叉连接设备（SDXC）"}],"answer":"B","explanation":"ADM的核心功能是在高速SDH信号中灵活分接或插入低速支路信号，无需中断整个链路传输；TM用于终端的复用/分接，REG用于信号再生放大，故B正确。","no":154},{"id":"1718790807135","type":"single","material":"","stem":"EDFA的基本组成不包括？","options":[{"label":"A","content":"掺铒光纤（EDF）"},{"label":"B","content":"泵浦光源"},{"label":"C","content":"波分复用器"},{"label":"D","content":"光检测器"}],"answer":"D","explanation":"EDFA由掺铒光纤（增益介质）、泵浦光源（提供能量）、波分复用器（合束泵浦光与信号光）、光隔离器（抑制反射光）组成；光检测器是光接收机部件，故D正确。","no":155},{"id":"1718790807136","type":"single","material":"","stem":"WDM系统中，信道隔离度的作用是？","options":[{"label":"A","content":"降低插入损耗"},{"label":"B","content":"抑制串扰"},{"label":"C","content":"提高功率"},{"label":"D","content":"拓宽带宽"}],"answer":"B","explanation":"信道隔离度表示不同波长信道间的串扰抑制能力，数值越大，相邻信道间的串扰越小，系统传输质量越稳定，故B正确。","no":156},{"id":"1718790807137","type":"single","material":"","stem":"PON系统中的“测距”机制目的是？","options":[{"label":"A","content":"测量光纤长度"},{"label":"B","content":"调整ONU定时，使逻辑距离相等"},{"label":"C","content":"检测光纤损耗"},{"label":"D","content":"定位故障点"}],"answer":"B","explanation":"PON中多个ONU共享光配线网（ODN），测距机制通过动态调节ONU的传输定时偏移，使各ONU到OLT的逻辑距离一致，避免时隙冲突，保障上行信号有序传输，故B正确。","no":157},{"id":"1718790807138","type":"single","material":"","stem":"光纤同轴电缆混合网（HFC）的传输介质是？","options":[{"label":"A","content":"仅光纤"},{"label":"B","content":"仅同轴电缆"},{"label":"C","content":"光纤+同轴电缆"},{"label":"D","content":"光纤+双绞线"}],"answer":"C","explanation":"HFC是光纤和同轴电缆的组合网络，光纤用于骨干网传输（OLT到光节点），同轴电缆用于用户入户（光节点到终端），实现语音、数据、视频的综合传输，故C正确。","no":158},{"id":"1718790807139","type":"single","material":"","stem":"光开关按工作原理分类，不包括？","options":[{"label":"A","content":"机械光开关"},{"label":"B","content":"固体光开关"},{"label":"C","content":"电光光开关"},{"label":"D","content":"放大光开关"}],"answer":"D","explanation":"光开关按工作原理分为机械光开关（物理光路切换）、固体光开关（材料特性变化）、电光光开关（电光效应）、声光光开关等，无“放大光开关”类别，故D正确。","no":159},{"id":"1718790807140","type":"single","material":"","stem":"下列关于LD和LED的区别，说法错误的是？","options":[{"label":"A","content":"LD有阈值电流，LED无阈值"},{"label":"B","content":"LD输出相干光，LED输出非相干光"},{"label":"C","content":"LD温度特性好，LED温度特性差"},{"label":"D","content":"LD适用于大容量长距离，LED适用于小容量短距离"}],"answer":"C","explanation":"LD的温度特性较差，温度升高会导致阈值电流增大、输出功率下降，需温控电路稳定；LED温度特性较好，无需温控，其余选项均为LD和LED的正确区别，故C正确。","no":160},{"id":"1718790807141","type":"single","material":"","stem":"某电商平台需要对用户的浏览、购买、收藏等行为数据进行分析，以预测用户可能感兴趣的商品并进行个性化推荐。在以下人工智能算法中，最适合完成该推荐任务的是（   ）","options":[{"label":"A","content":"朴素贝叶斯算法"},{"label":"B","content":"协同过滤算法"},{"label":"C","content":"线性回归算法"},{"label":"D","content":"聚类算法"}],"answer":"B","explanation":"协同过滤算法是个性化推荐领域的核心算法，通过分析用户行为相似度或物品相似度来生成推荐，广泛应用于电商、流媒体等场景；朴素贝叶斯多用于分类任务，线性回归用于数值预测，聚类用于无监督的群体划分，均不适合直接完成个性化推荐任务。","no":161},{"id":"1718790807142","type":"single","material":"","stem":"某金融机构需要对客户的交易数据进行分析，识别出潜在的欺诈交易行为，以降低资金风险。在以下人工智能算法中，最适合完成该异常检测任务的是（   ）","options":[{"label":"A","content":"逻辑回归算法"},{"label":"B","content":"孤立森林算法"},{"label":"C","content":"梯度提升树算法"},{"label":"D","content":"随机森林算法"}],"answer":"B","explanation":"孤立森林算法是专门用于异常检测的无监督算法，通过快速隔离异常样本实现高效识别，适合欺诈交易这类占比极低的异常场景；逻辑回归、梯度提升树、随机森林更适用于有监督的分类任务，需要大量标注的欺诈样本才能训练。","no":162},{"id":"1718790807143","type":"single","material":"","stem":"某医疗科研团队需要对患者的电子病历、检验报告等文本数据进行处理，提取关键病症、用药信息等内容，辅助医生进行诊断。在以下人工智能技术中，最适合完成该文本信息抽取任务的是（   ）","options":[{"label":"A","content":"计算机视觉技术"},{"label":"B","content":"自然语言处理技术"},{"label":"C","content":"语音识别技术"},{"label":"D","content":"强化学习技术"}],"answer":"B","explanation":"自然语言处理技术专注于处理和理解人类语言文本，可实现实体识别、信息抽取等功能，适合从医疗文本中提取关键信息；计算机视觉处理图像数据，语音识别处理音频数据，强化学习侧重决策优化，均不适合文本信息抽取任务。","no":163},{"id":"1718790807144","type":"single","material":"","stem":"某自动驾驶企业需要让车辆在复杂路况下实时感知周围环境，识别行人、车辆、交通标志等目标物体，以保障行驶安全。在以下人工智能算法中，最适合完成该目标检测任务的是（   ）","options":[{"label":"A","content":"K 均值聚类算法"},{"label":"B","content":"卷积神经网络算法"},{"label":"C","content":"主成分分析算法"},{"label":"D","content":"支持向量机算法"}],"answer":"B","explanation":"卷积神经网络（CNN）是计算机视觉领域的核心算法，擅长提取图像的空间特征，在目标检测、图像识别等任务中表现优异；K 均值聚类、主成分分析属于无监督降维 / 聚类算法，支持向量机更适合小样本分类任务，均不适合实时目标检测。","no":164},{"id":"1718790807145","type":"single","material":"","stem":"某语音交互公司需要开发智能语音助手，实现将用户的语音指令转化为文字指令并理解其意图。在以下人工智能技术中，最适合完成该语音转文字任务的是（   ）","options":[{"label":"A","content":"机器翻译技术"},{"label":"B","content":"语音识别技术"},{"label":"C","content":"情感分析技术"},{"label":"D","content":"知识图谱技术"}],"answer":"B","explanation":"语音识别技术的核心功能是将音频信号转化为文本数据，是智能语音助手的基础技术；机器翻译用于不同语言间的文本转换，情感分析用于判断文本情绪倾向，知识图谱用于知识存储与推理，均不适合语音转文字任务。","no":165},{"id":"1718790807146","type":"single","material":"","stem":"某城市交通管理部门需要对未来一周的交通流量进行预测，以优化信号灯配时、疏导拥堵路段。在以下人工智能算法中，最适合完成该时间序列预测任务的是（   ）","options":[{"label":"A","content":"循环神经网络算法"},{"label":"B","content":"决策树算法"},{"label":"C","content":"朴素贝叶斯算法"},{"label":"D","content":"层次聚类算法"}],"answer":"A","explanation":"循环神经网络（RNN）及其变体（如 LSTM）擅长处理序列数据，能捕捉时间维度上的依赖关系，适合交通流量、股价等时间序列预测任务；决策树、朴素贝叶斯属于分类算法，层次聚类属于无监督聚类算法，均不适合时间序列预测。","no":166},{"id":"1718790807147","type":"single","material":"","stem":"某电商平台需要对大量商品评论进行分析，判断用户评论的情感倾向（正面、负面、中性），以了解用户对商品的满意度。在以下人工智能算法中，最适合完成该情感分析任务的是（   ）","options":[{"label":"A","content":"逻辑回归算法"},{"label":"B","content":"循环神经网络算法"},{"label":"C","content":"支持向量机算法"},{"label":"D","content":"以上均可，其中循环神经网络更适合复杂语义场景"}],"answer":"D","explanation":"情感分析可通过传统机器学习算法（逻辑回归、支持向量机）或深度学习算法（循环神经网络）实现；传统算法依赖人工特征工程，适合简单场景，循环神经网络能自动提取文本语义特征，更适合复杂语义的情感判断。","no":167},{"id":"1718790807148","type":"single","material":"","stem":"某安防企业需要开发智能监控系统，实现对监控视频中异常行为（如打架、翻越围栏）的实时识别与预警。在以下人工智能技术中，最适合完成该视频异常检测任务的是（   ）","options":[{"label":"A","content":"图像分类技术"},{"label":"B","content":"时序动作识别技术"},{"label":"C","content":"图像分割技术"},{"label":"D","content":"特征匹配技术"}],"answer":"B","explanation":"时序动作识别技术基于视频序列数据，能捕捉连续帧中的动作特征，适合识别打架、翻越等时序性异常行为；图像分类仅能处理单帧图像，图像分割侧重像素级区域划分，特征匹配用于目标追踪，均不适合视频异常检测。","no":168},{"id":"1718790807149","type":"single","material":"","stem":"某金融机构需要对客户的信用数据进行评估，预测客户是否会出现逾期还款行为，以控制信贷风险。在以下人工智能算法中，最适合完成该信用评估分类任务的是（   ）","options":[{"label":"A","content":"线性回归算法"},{"label":"B","content":"梯度提升树算法"},{"label":"C","content":"K 近邻算法"},{"label":"D","content":"主成分分析算法"}],"answer":"B","explanation":"梯度提升树（如 XGBoost、LightGBM）在结构化数据分类任务中表现优异，能处理特征间的非线性关系，适合信用评估这类高维度、复杂特征的分类场景；线性回归用于数值预测，K 近邻计算效率低且对高维数据敏感，主成分分析用于降维，均不适合。","no":169},{"id":"1718790807150","type":"single","material":"","stem":"某教育科技公司需要开发智能阅卷系统，实现对学生手写答题卡的自动识别与评分。在以下人工智能技术中，最适合完成该手写字符识别任务的是（   ）","options":[{"label":"A","content":"卷积神经网络技术"},{"label":"B","content":"循环神经网络技术"},{"label":"C","content":"Transformer 技术"},{"label":"D","content":"生成对抗网络技术"}],"answer":"A","explanation":"卷积神经网络擅长提取图像中的局部特征，对手写字符的笔画、结构识别效果优异，是手写识别的主流技术；循环神经网络更适合序列数据，Transformer 侧重长距离依赖建模，生成对抗网络用于数据生成，均不是手写识别的最优选择。","no":170},{"id":"1718790807151","type":"single","material":"","stem":"某电商平台需要对商品图片进行自动打标，识别图片中的商品类别、颜色、款式等属性，以优化商品搜索与推荐。在以下人工智能算法中，最适合完成该多标签图像分类任务的是（   ）","options":[{"label":"A","content":"支持向量机算法"},{"label":"B","content":"卷积神经网络算法"},{"label":"C","content":"决策树算法"},{"label":"D","content":"朴素贝叶斯算法"}],"answer":"B","explanation":"卷积神经网络能同时提取图像的多层级特征，可实现多标签图像分类，适合商品属性识别这类需要同时输出多个标签的场景；支持向量机、决策树、朴素贝叶斯更适合单标签分类任务，难以高效处理多标签场景。","no":171},{"id":"1718790807152","type":"single","material":"","stem":"某游戏公司需要开发智能 NPC（非玩家角色），让 NPC 能在游戏中根据玩家行为做出自适应的决策与交互。在以下人工智能算法中，最适合完成该决策优化任务的是（   ）","options":[{"label":"A","content":"监督学习算法"},{"label":"B","content":"无监督学习算法"},{"label":"C","content":"强化学习算法"},{"label":"D","content":"半监督学习算法"}],"answer":"C","explanation":"强化学习算法通过 “试错 - 奖励” 机制训练智能体，使其在动态环境中学习最优决策策略，适合游戏 NPC 这类需要自适应交互的场景；监督学习依赖标注数据，无监督学习侧重数据聚类，半监督学习结合两者，均不适合动态决策优化。","no":172},{"id":"1718790807153","type":"single","material":"","stem":"某医疗影像公司需要对肺部 CT 影像进行分析，自动识别早期肺癌病灶，辅助医生进行诊断。在以下人工智能算法中，最适合完成该医学影像分割任务的是（   ）","options":[{"label":"A","content":"U-Net 网络算法"},{"label":"B","content":"随机森林算法"},{"label":"C","content":"K 均值聚类算法"},{"label":"D","content":"逻辑回归算法"}],"answer":"A","explanation":"U-Net 是专门用于医学影像分割的卷积神经网络变体，擅长捕捉图像细节特征，能实现病灶区域的精准分割；随机森林、K 均值聚类、逻辑回归均不适合像素级的影像分割任务。","no":173},{"id":"1718790807154","type":"single","material":"","stem":"某社交媒体平台需要对用户发布的文本内容进行自动审核，识别其中的暴力、色情等违规信息。在以下人工智能算法中，最适合完成该文本分类任务的是（   ）","options":[{"label":"A","content":"朴素贝叶斯算法"},{"label":"B","content":"Transformer 模型算法"},{"label":"C","content":"支持向量机算法"},{"label":"D","content":"决策树算法"}],"answer":"B","explanation":"Transformer 模型（如 BERT）能深度理解文本语义，在复杂文本分类任务中表现远超传统机器学习算法，适合违规信息识别这类需要精准语义判断的场景；朴素贝叶斯、支持向量机、决策树依赖人工特征，语义理解能力较弱。","no":174},{"id":"1718790807155","type":"single","material":"","stem":"某物流企业需要对未来一个月的货物运输量进行预测，以优化仓储布局与运力调配。在以下人工智能算法中，最适合完成该时间序列预测任务的是（   ）","options":[{"label":"A","content":"LSTM 神经网络算法"},{"label":"B","content":"线性回归算法"},{"label":"C","content":"K 近邻算法"},{"label":"D","content":"主成分分析算法"}],"answer":"A","explanation":"LSTM 是循环神经网络的变体，能有效解决长序列数据的梯度消失问题，擅长捕捉时间序列的长期依赖关系，适合货运量这类中长期时间序列预测；线性回归无法处理非线性趋势，K 近邻计算效率低，主成分分析用于降维，均不适合。","no":175},{"id":"1718790807156","type":"single","material":"","stem":"某零售企业需要对门店的顾客群体进行划分，识别出不同消费习惯的客户群体，以制定精准的营销策略。在以下人工智能算法中，最适合完成该客户分群任务的是（   ）","options":[{"label":"A","content":"逻辑回归算法"},{"label":"B","content":"K 均值聚类算法"},{"label":"C","content":"梯度提升树算法"},{"label":"D","content":"支持向量机算法"}],"answer":"B","explanation":"K 均值聚类是无监督学习算法，通过计算样本间的距离将相似样本归为一类，适合客户分群这类无标注数据的群体划分任务；逻辑回归、梯度提升树、支持向量机均属于有监督学习算法，需要标注标签才能训练。","no":176},{"id":"1718790807157","type":"single","material":"","stem":"某智能硬件公司需要开发语音唤醒功能，让设备在听到特定唤醒词（如 “小 X”）时自动激活。在以下人工智能技术中，最适合完成该唤醒词识别任务的是（   ）","options":[{"label":"A","content":"语音识别技术"},{"label":"B","content":"声纹识别技术"},{"label":"C","content":"关键词检测技术"},{"label":"D","content":"情感分析技术"}],"answer":"C","explanation":"关键词检测技术专注于识别音频中的特定关键词，是语音唤醒功能的核心技术，相比完整语音识别更高效、低功耗；语音识别用于全量转写，声纹识别用于身份验证，情感分析用于情绪判断，均不适合唤醒词识别。","no":177},{"id":"1718790807158","type":"single","material":"","stem":"某广告公司需要对广告投放效果进行预测，根据用户特征、广告素材等数据预测广告的点击率，以优化投放策略。在以下人工智能算法中，最适合完成该点击率预测任务的是（   ）","options":[{"label":"A","content":"逻辑回归算法"},{"label":"B","content":"梯度提升树算法"},{"label":"C","content":"神经网络算法"},{"label":"D","content":"以上均可，其中梯度提升树与神经网络更适合复杂场景"}],"answer":"D","explanation":"点击率预测属于分类任务（点击 / 未点击），逻辑回归、梯度提升树、神经网络均可实现；逻辑回归简单高效适合 baseline，梯度提升树擅长处理结构化数据，神经网络能捕捉高阶特征交互，更适合复杂业务场景。","no":178},{"id":"1718790807159","type":"single","material":"","stem":"某农业科技公司需要对农田的卫星遥感图像进行分析，识别出不同作物的种植区域与生长状况，以辅助农业生产决策。在以下人工智能算法中，最适合完成该遥感图像分类任务的是（   ）","options":[{"label":"A","content":"卷积神经网络算法"},{"label":"B","content":"支持向量机算法"},{"label":"C","content":"决策树算法"},{"label":"D","content":"朴素贝叶斯算法"}],"answer":"A","explanation":"卷积神经网络擅长提取遥感图像的光谱、空间特征，能精准识别不同作物类别与生长状况，是农业遥感图像分析的主流技术；支持向量机、决策树、朴素贝叶斯依赖人工特征提取，效果远不如卷积神经网络。","no":179},{"id":"1718790807160","type":"single","material":"","stem":"某金融科技公司需要开发智能客服系统，让客服机器人能理解用户的咨询意图并给出精准回复。在以下人工智能技术中，最适合完成该意图识别任务的是（   ）","options":[{"label":"A","content":"文本分类技术"},{"label":"B","content":"机器翻译技术"},{"label":"C","content":"文本生成技术"},{"label":"D","content":"知识图谱技术"}],"answer":"A","explanation":"意图识别本质是文本分类任务，通过将用户咨询文本归类到不同意图类别（如查询余额、挂失银行卡），是智能客服的核心技术；机器翻译用于语言转换，文本生成用于回复生成，知识图谱用于知识查询，均不直接完成意图识别。","no":180},{"id":"1718790807161","type":"single","material":"","stem":"某安防企业需要对监控视频中的行人进行实时追踪，识别行人的身份与运动轨迹，以保障公共安全。在以下人工智能算法中，最适合完成该多目标追踪任务的是（   ）","options":[{"label":"A","content":"卷积神经网络算法"},{"label":"B","content":"目标检测 + 卡尔曼滤波算法"},{"label":"C","content":"循环神经网络算法"},{"label":"D","content":"生成对抗网络算法"}],"answer":"B","explanation":"多目标追踪通常结合目标检测算法（如 YOLO）识别行人，再通过卡尔曼滤波等算法预测目标运动轨迹、关联不同帧的同一目标；卷积神经网络仅负责目标检测，循环神经网络用于序列处理，生成对抗网络用于数据生成，均无法单独完成多目标追踪。","no":181},{"id":"1718790807162","type":"single","material":"","stem":"某教育科技公司需要对学生的学习行为数据进行分析，预测学生可能存在的学习困难科目，以提供个性化的学习辅导。在以下人工智能算法中，最适合完成该学习预警任务的是（   ）","options":[{"label":"A","content":"逻辑回归算法"},{"label":"B","content":"梯度提升树算法"},{"label":"C","content":"循环神经网络算法"},{"label":"D","content":"以上均可，具体选择取决于数据类型"}],"answer":"D","explanation":"学习预警属于分类或回归任务，若数据为结构化行为数据（如作业完成率、考试分数），梯度提升树、逻辑回归更高效；若数据为时序学习记录（如每日学习时长），循环神经网络更适合捕捉时序特征。","no":182},{"id":"1718790807163","type":"single","material":"","stem":"某设计公司需要利用人工智能技术生成新的产品外观设计图，辅助设计师进行创意灵感激发。在以下人工智能算法中，最适合完成该图像生成任务的是（   ）","options":[{"label":"A","content":"卷积神经网络算法"},{"label":"B","content":"生成对抗网络算法"},{"label":"C","content":"循环神经网络算法"},{"label":"D","content":"支持向量机算法"}],"answer":"B","explanation":"生成对抗网络（GAN）通过 “生成器 - 判别器” 对抗训练，能生成高质量的新图像数据，是当前图像生成领域的核心技术；卷积神经网络用于图像识别，循环神经网络用于序列生成，支持向量机用于分类，均不适合图像生成。","no":183},{"id":"1718790807164","type":"single","material":"","stem":"某医疗科研团队需要对患者的基因序列数据进行分析，识别出与特定疾病相关的基因变异位点，以辅助疾病的早期筛查。在以下人工智能算法中，最适合完成该基因序列分析任务的是（   ）","options":[{"label":"A","content":"Transformer 模型算法"},{"label":"B","content":"卷积神经网络算法"},{"label":"C","content":"循环神经网络算法"},{"label":"D","content":"朴素贝叶斯算法"}],"answer":"A","explanation":"Transformer 模型擅长处理长序列数据，能捕捉基因序列中的长距离依赖关系，适合基因变异位点识别这类生物序列分析任务；卷积神经网络适合局部特征提取，循环神经网络对超长序列处理效率低，朴素贝叶斯无法处理复杂序列特征。","no":184},{"id":"1718790807165","type":"single","material":"","stem":"某电商平台需要对商品的搜索关键词进行自动补全，根据用户已输入的字符预测后续可能的关键词，以提升搜索体验。在以下人工智能算法中，最适合完成该语言模型任务的是（   ）","options":[{"label":"A","content":"N-gram 语言模型算法"},{"label":"B","content":"Transformer 模型算法"},{"label":"C","content":"循环神经网络算法"},{"label":"D","content":"以上均可，其中 Transformer 模型效果最优"}],"answer":"D","explanation":"关键词补全依赖语言模型预测下一个字符 / 词，N-gram 是传统统计语言模型，循环神经网络、Transformer 是深度学习语言模型；Transformer 模型能捕捉更长距离的语义依赖，在当前场景下效果最优。","no":185},{"id":"1718790807166","type":"single","material":"","stem":"某能源企业需要对风力发电机的运行数据进行分析，预测发电机可能出现的故障类型，以提前进行维护、降低停机损失。在以下人工智能算法中，最适合完成该故障诊断任务的是（   ）","options":[{"label":"A","content":"随机森林算法"},{"label":"B","content":"卷积神经网络算法"},{"label":"C","content":"循环神经网络算法"},{"label":"D","content":"梯度提升树算法"}],"answer":"D","explanation":"风力发电机故障诊断依赖结构化的运行数据（如转速、温度、振动），梯度提升树算法能高效处理高维结构化数据，捕捉特征间的非线性关系，适合故障分类与预测；随机森林效果略逊于梯度提升树，卷积神经网络、循环神经网络更适合时序 / 图像数据。","no":186},{"id":"1718790807167","type":"single","material":"","stem":"某社交媒体平台需要对用户上传的图片进行自动审核，识别其中的违规内容（如暴力、色情图片）。在以下人工智能算法中，最适合完成该图像内容审核任务的是（   ）","options":[{"label":"A","content":"卷积神经网络算法"},{"label":"B","content":"支持向量机算法"},{"label":"C","content":"决策树算法"},{"label":"D","content":"K 近邻算法"}],"answer":"A","explanation":"卷积神经网络能提取图像的深层视觉特征，精准识别违规图像内容，是当前图像内容审核的主流技术；支持向量机、决策树、K 近邻依赖人工特征提取，对复杂图像内容的识别效果远不如卷积神经网络。","no":187},{"id":"1718790807168","type":"single","material":"","stem":"某智能交通公司需要开发车路协同系统，让车辆与道路设施之间实现实时数据交互，优化交通流。在以下人工智能技术中，最适合完成该多智能体协同决策任务的是（   ）","options":[{"label":"A","content":"强化学习技术"},{"label":"B","content":"监督学习技术"},{"label":"C","content":"无监督学习技术"},{"label":"D","content":"半监督学习技术"}],"answer":"A","explanation":"强化学习中的多智能体强化学习算法，能让多个智能体（车辆、道路设施）在动态环境中协同学习最优决策策略，适合车路协同这类多主体交互场景；监督学习依赖标注数据，无监督学习侧重聚类，均不适合协同决策。","no":188},{"id":"1718790807169","type":"single","material":"","stem":"某出版公司需要对大量书籍文本进行自动摘要生成，提取文本的核心内容，以方便读者快速了解书籍主旨。在以下人工智能算法中，最适合完成该文本摘要任务的是（   ）","options":[{"label":"A","content":"循环神经网络算法"},{"label":"B","content":"Transformer 模型算法"},{"label":"C","content":"朴素贝叶斯算法"},{"label":"D","content":"决策树算法"}],"answer":"B","explanation":"Transformer 模型（如 BART、T5）擅长处理文本生成任务，能生成流畅、准确的摘要内容，是当前文本摘要的主流技术；循环神经网络存在长距离依赖问题，朴素贝叶斯、决策树无法完成文本生成任务。","no":189},{"id":"1718790807170","type":"single","material":"","stem":"某体育科技公司需要对运动员的运动视频进行分析，识别运动员的动作姿态（如投篮、跑步），以辅助训练优化。在以下人工智能算法中，最适合完成该姿态估计任务的是（   ）","options":[{"label":"A","content":"卷积神经网络算法"},{"label":"B","content":"循环神经网络算法"},{"label":"C","content":"Transformer 模型算法"},{"label":"D","content":"以上均可，其中卷积神经网络是基础"}],"answer":"D","explanation":"姿态估计依赖卷积神经网络提取图像特征，定位人体关键点；结合循环神经网络或 Transformer 模型，可进一步处理视频序列的时序信息，提升姿态识别的连贯性与准确性，因此卷积神经网络是基础，深度学习模型可组合使用。","no":190}]};
